// Regenerate with `npm run mock:schema` while the devhost is running.
export const SCHEMA_SDL = "schema {\n  query: RootQuery\n  mutation: RootMutation\n  subscription: LifecycleSubscriptions\n}\n\n\"\"\"\nThe purpose of the `cost` directive is to define a `weight` for GraphQL types, fields, and arguments. Static analysis can use these weights when calculating the overall cost of a query or response.\n\"\"\"\ndirective @cost(\n  \"\"\"\n  The `weight` argument defines what value to add to the overall cost for every appearance, or possible appearance, of a type, field, argument, etc.\n  \"\"\"\n  weight: String!\n) on SCALAR | OBJECT | FIELD_DEFINITION | ARGUMENT_DEFINITION | ENUM | INPUT_FIELD_DEFINITION\n\n\"\"\"\nEvent payload published by lifecycle hooks and consumed by GraphQL subscriptions.\n\"\"\"\ntype TrainLifecycleEvent {\n  metadataId: Long!\n  externalId: String!\n  trainName: String!\n  trainState: TrainState!\n  timestamp: DateTime!\n  failureJunction: String\n  failureReason: String\n  hostName: String\n  hostEnvironment: String\n\n  \"\"\"\n  This event's position in the subscription: 1 for the first event and one more for each after it. A jump of more than one means events were lost on the way to this subscriber; refetch what you show. The live feed is lossy under load.\n  \"\"\"\n  sequence: Long!\n  output: Any\n}\n\n\"\"\"\nWhat happened to one step of a run: the payload of the onJunctionEvent subscription.\n\"\"\"\ntype JunctionEvent {\n  \"\"\"The run's execution id.\"\"\"\n  metadataId: Long!\n\n  \"\"\"The run's stable external id.\"\"\"\n  externalId: String!\n\n  \"\"\"The train's canonical name (its interface's full name).\"\"\"\n  trainName: String!\n\n  \"\"\"What happened to the step.\"\"\"\n  eventType: JunctionEventType!\n\n  \"\"\"When the event was published (UTC).\"\"\"\n  timestamp: DateTime!\n\n  \"\"\"The step.\"\"\"\n  junction: JunctionStep!\n\n  \"\"\"\n  This event's position in the subscription: 1 for the first event and one more for each after it. A jump of more than one means events were lost on the way to this subscriber. The feed is shared by every run on the host, so a gap can come from another run's steps rather than this one's. In the operations view read operations.junctionRuns again to recover; a broadcast subscriber cannot read it, and has no way to recover a gap. The live feed is lossy under load.\n  \"\"\"\n  sequence: Long!\n}\n\n\"\"\"\nOne step of a run: a junction that ran, a question a routing step asked, or the track it took.\nThe onJunctionEvent subscription carries one per event, and\noperations.junctionRuns returns a run's steps as AddJunctionEvents() recorded them.\n\"\"\"\ntype JunctionStep {\n  \"\"\"\n  Where the step falls in the run, from 0. A junction's start and end share it.\n  \"\"\"\n  position: Int!\n\n  \"\"\"What the step is.\"\"\"\n  kind: JunctionRunKind!\n\n  \"\"\"The junction's class name without its namespace, or a question's key.\"\"\"\n  name: String!\n\n  \"\"\"Where the step stands.\"\"\"\n  state: JunctionRunState!\n\n  \"\"\"\n  When the junction started, or when the question was answered or the track taken (UTC).\n  \"\"\"\n  startedAt: DateTime!\n\n  \"\"\"When the junction returned (UTC), or null while it runs.\"\"\"\n  endedAt: DateTime\n\n  \"\"\"Milliseconds from StartedAt to EndedAt, or null while it runs.\"\"\"\n  durationMs: Float\n\n  \"\"\"How a failed junction's failure is classified; null unless it failed.\"\"\"\n  failureClass: FailureClass\n\n  \"\"\"\n  The type name of the exception a junction failed or was cancelled with, never its message.\n  \"\"\"\n  failureException: String\n\n  \"\"\"The question's key, for a question or a track.\"\"\"\n  questionKey: String\n\n  \"\"\"\n  The answer the run acted on, or null for a junction, a refused answer and a withheld one.\n  \"\"\"\n  answer: String\n\n  \"\"\"How sure the decider was, for a choice or a score; null when withheld.\"\"\"\n  confidence: Float\n\n  \"\"\"True when the answer came from an earlier run rather than a decider.\"\"\"\n  replayed: Boolean!\n\n  \"\"\"\n  The full name of the decider's type. Live events only; the recorded timeline does not keep it.\n  \"\"\"\n  decider: String\n\n  \"\"\"\n  True when the question is about a [TraxSensitive] type, so its answer and confidence are absent.\n  \"\"\"\n  answerWithheld: Boolean!\n\n  \"\"\"\n  Which attempt of its manifest the run is, or null for a run with no manifest.\n  \"\"\"\n  attempt: Int\n\n  \"\"\"\n  True when Name is (withheld): the step is on a decision track, and its\n  name would give away an answer this caller is not shown.\n  \"\"\"\n  nameWithheld: Boolean!\n\n  \"\"\"\n  The position of the latest routing step before this one, or null before any. Every step\n  after a route, a junction, a question or a further route, counts as on its track.\n  \"\"\"\n  trackPosition: Int\n\n  \"\"\"\n  The id of the declared node this step ran for, as operations.declaredChain names it. Null for a step recorded before node ids were, and wherever the step's name is withheld, since the id names the track.\n  \"\"\"\n  nodeId: String\n\n  \"\"\"\n  The path of the Parallel branch the step ran in, such as Parallel#0/cocitation, or null outside any branch. Withheld wherever the step's name is.\n  \"\"\"\n  branchPath: String\n}\n\n\"\"\"\nPredefined operational queries: health, trains, manifests, manifest groups, execution\nhistory, and the nested deadLetters namespace.\n\"\"\"\ntype OperationsQueries {\n  \"\"\"\n  Nested namespace exposing dead letter queries (deadLetters, deadLetter).\n  \"\"\"\n  deadLetters: DeadLetterQueries!\n\n  \"\"\"Nested namespace exposing work queue queries (workQueues, workQueue).\"\"\"\n  workQueue: WorkQueueQueries!\n\n  \"\"\"Nested namespace exposing manifest group queries (graph).\"\"\"\n  manifestGroups: ManifestGroupQueries!\n\n  \"\"\"\n  Nested namespace exposing log queries (paginated reads of the log records trains write).\n  \"\"\"\n  logs: LogQueries!\n\n  \"\"\"\n  Nested namespace exposing dashboard / server metrics. Same data the dashboard\n  Index page renders.\n  \"\"\"\n  metrics: MetricsQueries!\n\n  \"\"\"\n  Nested namespace exposing live scheduler runtime config (what the dashboard's\n  ServerSettingsPage reads).\n  \"\"\"\n  config: ConfigQueries!\n\n  \"\"\"\n  The current health summary: queue depth, running and recently failed executions, and dead\n  letters awaiting intervention. Computed on every call.\n  \"\"\"\n  health: HealthStatus!\n\n  \"\"\"\n  Canonical FullNames of the internal/administrative scheduler trains (JobDispatcher,\n  ManifestManager, JobRunner, cleanup, etc.). Clients filter these out of live subscription\n  feeds; the executions query filters them server-side via hideAdminTrains.\n  \"\"\"\n  adminTrainNames: [String!]!\n\n  \"\"\"\n  Every train registered with this host, with its input schema, authorization requirements and\n  how it is exposed in GraphQL.\n  \"\"\"\n  trains(\n    \"\"\"Leave out the scheduler's own internal trains (see adminTrainNames).\"\"\"\n    hideAdminTrains: Boolean! = false\n  ): [TrainInfo!]!\n\n  \"\"\"\n  The observational effects registered in THIS process, with their enabled + toggleable state\n  and, for a factory that exposes runtime settings, those settings: as JSON, and as\n  fields an editor can be built from. Read through\n  IEffectSettingsService, the call the dashboard's effects page makes. The\n  registry and each settings object are in-memory per-process singletons, so this reflects the\n  API host only, not the scheduler/worker processes where effects run;\n  operations.setEffectEnabled and operations.configureEffect change them here.\n  Empty when the host registers no effect registry.\n  \"\"\"\n  effects: [EffectInfo!]!\n\n  \"\"\"\n  One run's recorded decisions, in the order it made them: each question it asked a decider,\n  the answer it acted on (or refused), and the tracks routing steps took on it. Read through\n  CancellationToken), the read the dashboard's run\n  page makes. Empty for a run that recorded none, and for an id with no run. A run's replay\n  link is on executionDetail (replayDecisionsOf, replayAbandoned).\n  \"\"\"\n  decisions(\n    \"\"\"The run's id.\"\"\"\n    metadataId: Long!\n\n    \"\"\"Only decisions recorded after this one (a page's nextCursor).\"\"\"\n    afterId: Long\n\n    \"\"\"The page size, clamped to 1 through 500.\"\"\"\n    take: Int! = 50\n  ): DecisionPage!\n\n  \"\"\"\n  The schedule exclusion windows configured on a manifest (the days/dates/ranges/time windows\n  during which it is intentionally skipped). Empty when the manifest has none or does not\n  exist. Backs the exclusions panel on the dashboard's manifest detail page.\n  \"\"\"\n  manifestExclusions(manifestId: Long!): [ManifestExclusion!]!\n\n  \"\"\"\n  A page of manifests, newest first. Pass the previous page's nextCursor as\n  afterId to page deeply; skip is ignored when afterId is set. Carries no\n  train input; manifestDetail does.\n  \"\"\"\n  manifests(\n    \"\"\"\n    How many manifests to skip (negative is treated as 0; above 10,000 is refused with TRAX_SKIP_TOO_DEEP, so page deeper with afterId).\n    \"\"\"\n    skip: Int! = 0\n\n    \"\"\"The page size, clamped to 1 through 500.\"\"\"\n    take: Int! = 25\n\n    \"\"\"Only enabled (true) or disabled (false) manifests.\"\"\"\n    isEnabled: Boolean\n\n    \"\"\"Only manifests with this schedule type.\"\"\"\n    scheduleType: ScheduleType\n\n    \"\"\"Only manifests whose train name contains this text.\"\"\"\n    nameContains: String\n\n    \"\"\"Only manifests older than this id (a keyset cursor).\"\"\"\n    afterId: Long\n\n    \"\"\"Only manifests in this group.\"\"\"\n    manifestGroupId: Long\n\n    \"\"\"\n    Leave out the scheduler's own internal trains' manifests (see adminTrainNames).\n    \"\"\"\n    hideAdminTrains: Boolean! = false\n  ): PagedResultOfManifestSummary!\n\n  \"\"\"\n  One manifest by id, without its train input, or null when none has that id.\n  \"\"\"\n  manifest(id: Long!): ManifestSummary\n\n  \"\"\"\n  Full detail for one manifest, including the train input it runs with. The input is on this\n  single-row read only, never on the manifests list, the way an execution's input is on\n  executionDetail alone. The manifest keeps it unmasked because its runs start from it;\n  here each [TraxSensitive] member reads {\"_redacted\": true}, and an input this\n  host cannot read as its type is masked whole. Returns null when the manifest does\n  not exist.\n  \"\"\"\n  manifestDetail(id: Long!): ManifestDetail\n\n  \"\"\"\n  Execution roll-up for a single manifest: run counts by state plus the most recent run and\n  most recent successful run. Backs the summary cards on the dashboard's manifest detail page,\n  and reads through the same IOperationsService call. A manifest with no runs,\n  or an id with no manifest, gets zeros and nulls.\n  \"\"\"\n  manifestStats(manifestId: Long!): ManifestExecutionStats!\n\n  \"\"\"\n  Execution roll-up for one train, keyed by its interface FullName (the name every\n  execution records). Backs the per-train detail page.\n  \"\"\"\n  trainStats(trainName: String!): TrainExecutionStats!\n\n  \"\"\"\n  The processes that have executed trains, rolled up from the recorded executions by\n  HostInstanceId: last-seen, total executions, and how many are still running. Backs the\n  dashboard's cluster view. It aggregates over every recorded execution (like the dashboard\n  metrics), so it is meant for occasional refresh, not a hot poll.\n  \"\"\"\n  hosts: [HostInfo!]!\n\n  \"\"\"\n  A page of executions. Pass the previous page's nextCursor as afterId to page\n  deeply in either order; skip is ignored when afterId is set. Unfiltered, the\n  total may be an estimate (isEstimatedCount). Filtered by failure text, it counts at\n  most 10,000 matches: past that it reads 10,000 with isCountCapped true, a lower bound.\n  Under any other filter it is exact. Carries no input, output or stack trace;\n  executionDetail does.\n  \"\"\"\n  executions(\n    \"\"\"\n    How many executions to skip (negative is treated as 0; above 10,000 is refused with TRAX_SKIP_TOO_DEEP, so page deeper with afterId).\n    \"\"\"\n    skip: Int! = 0\n\n    \"\"\"The page size, clamped to 1 through 500.\"\"\"\n    take: Int! = 25\n\n    \"\"\"Only executions in this state.\"\"\"\n    trainState: TrainState\n\n    \"\"\"\n    Only executions of this train (the train interface's full name, matched exactly).\n    \"\"\"\n    trainName: String\n\n    \"\"\"Only executions that started at or after this time (UTC).\"\"\"\n    startedAfter: DateTime\n\n    \"\"\"Only executions that started at or before this time (UTC).\"\"\"\n    startedBefore: DateTime\n\n    \"\"\"Newest first (the default) or oldest first.\"\"\"\n    order: SortOrder! = NEWEST\n\n    \"\"\"A keyset cursor: the page continues after this id in the chosen order.\"\"\"\n    afterId: Long\n\n    \"\"\"Only executions scheduled by this manifest.\"\"\"\n    manifestId: Long\n\n    \"\"\"Only executions scheduled by a manifest in this group.\"\"\"\n    manifestGroupId: Long\n\n    \"\"\"Leave out the scheduler's own internal trains.\"\"\"\n    hideAdminTrains: Boolean! = false\n\n    \"\"\"Only executions whose failure was classified this way.\"\"\"\n    failureClass: FailureClass\n\n    \"\"\"Only the execution with this external id (matched exactly).\"\"\"\n    externalId: String\n\n    \"\"\"Only executions started from inside this execution's run.\"\"\"\n    parentId: Long\n\n    \"\"\"Only executions run on the machine with this name (matched exactly).\"\"\"\n    hostName: String\n\n    \"\"\"\n    Only executions whose failure reason contains this text, ignoring case.\n    \"\"\"\n    failureReasonContains: String\n\n    \"\"\"\n    Only executions that failed in the junction with this name (matched exactly).\n    \"\"\"\n    failureJunction: String\n  ): PagedResultOfExecutionSummary!\n\n  \"\"\"\n  One execution by id, without input, output or stack trace, or null when none has that id.\n  \"\"\"\n  execution(id: Long!): ExecutionSummary\n\n  \"\"\"\n  Full detail for one execution, including its input, output, stack trace and the number of\n  executions it started, or null when none has that id.\n  \"\"\"\n  executionDetail(id: Long!): ExecutionDetail\n\n  \"\"\"\n  Paginated child executions of a parent: the executions it started, newest first.\n  Keyset-paginated on id like the top-level executions list.\n  \"\"\"\n  executionChildren(parentId: Long!, take: Int! = 25, afterId: Long): PagedResultOfExecutionSummary!\n\n  \"\"\"\n  The steps of one execution, in the order it reached them, as AddJunctionEvents()\n  recorded them: each junction that ran, each question a routing step asked and the track it\n  took. Empty for an execution with none recorded, and for an id with no execution.\n  \"\"\"\n  junctionRuns(\n    \"\"\"The execution's id.\"\"\"\n    metadataId: Long!\n\n    \"\"\"Only steps after this position (a keyset cursor for the next page).\"\"\"\n    afterPosition: Int\n\n    \"\"\"The page size, clamped to 1 through 500.\"\"\"\n    take: Int! = 500\n  ): [JunctionStep!]!\n\n  \"\"\"\n  The declared chain of the registered train named train, its canonical\n  name (the interface's full name, as execution.name carries it), as a graph: every\n  step in order, each routing step's tracks, and a hash that changes with the chain. Null when\n  no registered train has that name, or its chain cannot be read outside a request.\n  \"\"\"\n  declaredChain(\n    \"\"\"The train's canonical name.\"\"\"\n    train: String!\n  ): ChainGraph\n\n  \"\"\"\n  One execution drawn on its train's declared chain: each node with the steps the run\n  recorded for it and where it stands (completed, failed, skipped on a track not taken, not\n  reached), the track each routing step took, and the steps that match no node. Null for an\n  id with no execution.\n  \"\"\"\n  runGraph(\n    \"\"\"The execution's id.\"\"\"\n    metadataId: Long!\n  ): RunGraph\n\n  \"\"\"\n  A page of state-machine instances, system-owned and user-owned alike, newest first by when\n  each was last written. Each carries its machine, owner kind, id, state, version,\n  timestamps and whether it waits on a train run it invoked; never its context or its\n  owner's key. Page with skip and take; there is no cursor, because the order\n  is by a time that moves. The total counts at most 10,000 instances: past that it reads\n  10,000 with isCountCapped true, and machineInstanceCounts has the exact\n  numbers by state.\n  \"\"\"\n  machineInstances(\n    \"\"\"Only instances of this machine (its id, matched exactly).\"\"\"\n    machine: String\n\n    \"\"\"Only instances in this state (matched exactly).\"\"\"\n    state: String\n\n    \"\"\"Only instances a user owns, or only those the system owns.\"\"\"\n    ownerKind: SnapshotOwnerKind\n\n    \"\"\"\n    How many instances to skip (negative is treated as 0; above 10,000 is refused with TRAX_SKIP_TOO_DEEP).\n    \"\"\"\n    skip: Int! = 0\n\n    \"\"\"The page size, clamped to 1 through 500.\"\"\"\n    take: Int! = 25\n  ): PagedResultOfMachineInstance!\n\n  \"\"\"\n  One state-machine instance with the train runs it invoked (invokedRuns, newest\n  first, at most 50, the one its state waits on marked isLive; a user's draft lists\n  only its live run), or null when none matches. The owner kind is always named,\n  because a user can hold a draft under the same id as a system instance. A system instance\n  is unique by machine and id; a user's draft is named by its rowId too (refused with\n  TRAX_ROW_ID_REQUIRED without one), because several users can each hold a draft\n  under one id and an operator is not shown whose a draft is.\n  \"\"\"\n  machineInstance(\n    \"\"\"The machine's id.\"\"\"\n    machine: String!\n\n    \"\"\"Who owns the instance.\"\"\"\n    ownerKind: SnapshotOwnerKind!\n\n    \"\"\"The instance or draft id.\"\"\"\n    id: UUID!\n\n    \"\"\"The row's key, from the list; required for a user's draft.\"\"\"\n    rowId: Long\n  ): MachineInstanceDetail\n\n  \"\"\"\n  How many instances each machine has in each state, for each owner kind, ordered by machine,\n  state and owner kind. Exact. Read through the call the dashboard's State machines page\n  makes for its counts, which each host keeps for 5 seconds per machine filter, so every\n  caller polling them shares one read and a count can be that old.\n  \"\"\"\n  machineInstanceCounts(\n    \"\"\"Only this machine's counts; omitted, every machine's.\"\"\"\n    machine: String\n  ): [MachineInstanceCount!]!\n\n  \"\"\"\n  Nested namespace exposing persisted-operation queries (paged list,\n  single lookup, audit history). It groups fields and reads nothing itself, so it is as open\n  as the operations field above it: the gate the host declared for the namespace is\n  on that field, and every field under it is behind it.\n  \"\"\"\n  persistedOperations: PersistedOperationQueries!\n}\n\n\"\"\"\nQueries for dead letter records with optional status filtering and pagination.\n\"\"\"\ntype DeadLetterQueries {\n  \"\"\"\n  A page of dead letters, newest first. Pass the previous page's nextCursor as\n  afterId to page deeply; skip is ignored when afterId is set.\n  \"\"\"\n  deadLetters(\n    \"\"\"\n    How many dead letters to skip (negative is treated as 0; above 10,000 is refused with TRAX_SKIP_TOO_DEEP, so page deeper with afterId).\n    \"\"\"\n    skip: Int! = 0\n\n    \"\"\"The page size, clamped to 1 through 500.\"\"\"\n    take: Int! = 25\n\n    \"\"\"Only dead letters in this status; null for all.\"\"\"\n    status: DeadLetterStatus\n\n    \"\"\"Only dead letters older than this id (a keyset cursor).\"\"\"\n    afterId: Long\n\n    \"\"\"Only dead letters of this manifest.\"\"\"\n    manifestId: Long\n  ): PagedResultOfDeadLetterSummary!\n\n  \"\"\"\n  A requeue-all job requeueAllDeadLetters started on this node, or null when this\n  node does not know the id: it was started on another node, this node has restarted since,\n  or it finished more than 24 hours ago. A job is read on the node that started it; the\n  backlog itself is deadLetters(status: AWAITING_INTERVENTION).totalCount on any node.\n  \"\"\"\n  requeueAllJob(id: UUID!): DeadLetterRequeueJob\n\n  \"\"\"One dead letter by id, or null when none has that id.\"\"\"\n  deadLetter(id: Long!): DeadLetterSummary\n}\n\n\"\"\"\nQueries for the work queue: pending, dispatched, and cancelled entries with optional\nstatus / train name filtering and keyset pagination.\n\"\"\"\ntype WorkQueueQueries {\n  \"\"\"\n  A page of work queue entries, newest first. Pass the previous page's nextCursor as\n  afterId to page deeply; skip is ignored when afterId is set. Carries no\n  train input; detail does.\n  \"\"\"\n  workQueues(\n    \"\"\"\n    How many entries to skip (negative is treated as 0; above 10,000 is refused with TRAX_SKIP_TOO_DEEP, so page deeper with afterId).\n    \"\"\"\n    skip: Int! = 0\n\n    \"\"\"The page size, clamped to 1 through 500.\"\"\"\n    take: Int! = 25\n\n    \"\"\"Only entries in this status.\"\"\"\n    status: WorkQueueStatus\n\n    \"\"\"Only entries for this train (matched exactly).\"\"\"\n    trainName: String\n\n    \"\"\"Only entries older than this id (a keyset cursor).\"\"\"\n    afterId: Long\n\n    \"\"\"Only entries that serialize on this subject (matched exactly).\"\"\"\n    subjectKey: String\n\n    \"\"\"Only entries queued for this manifest.\"\"\"\n    manifestId: Long\n  ): PagedResultOfWorkQueueSummary!\n\n  \"\"\"\n  One work queue entry by id, without its train input, or null when none has that id.\n  \"\"\"\n  workQueue(id: Long!): WorkQueueSummary\n\n  \"\"\"\n  Full detail for one work queue entry: its train input, and for a queued entry with a\n  subject, what it is waiting on. The input is on this single-row read only, never on the\n  workQueues list, the way an execution's input is on executionDetail alone.\n  The entry keeps the input unmasked because the run starts from it; here each\n  [TraxSensitive] member reads {\"_redacted\": true}, as in an execution's\n  recorded input, and an input this host cannot read as its type is masked whole.\n  Returns null when the entry does not exist.\n  \"\"\"\n  detail(id: Long!): WorkQueueDetail\n}\n\n\"\"\"\nQueries under operations.manifestGroups. Holds the paginated list of manifest\ngroups, single-group lookup, and the 1-hop cross-group dependency neighborhood used\nby the dashboard's DAG visualisation. graph goes through the same service the\ndashboard uses, so both see identical nodes and edges.\n\"\"\"\ntype ManifestGroupQueries {\n  \"\"\"\n  Paginated list of manifest groups, newest first. Lives here (not on\n  OperationsQueries) because the parent's manifestGroups field\n  returns this namespace; a sibling field with the same camelCased name would\n  collide and HotChocolate would silently drop one.\n  \"\"\"\n  groups(skip: Int! = 0, take: Int! = 25, nameContains: String, afterId: Long): PagedResultOfManifestGroupSummary!\n\n  \"\"\"\n  Single-group lookup by id. Returns null when the group does not exist.\n  Required by the dashboard's group detail page so it can pre-populate the\n  maxActiveJobs, priority, and isEnabled form before the\n  operator submits a patch.\n  \"\"\"\n  group(id: Long!): ManifestGroupSummary\n\n  \"\"\"\n  Execution roll-up for a set of manifest groups: manifest count, executions by state, and\n  last run per group. Batched so the dashboard's groups list fetches stats for just the\n  visible page in one round-trip, through the same IOperationsService call.\n  Every requested id gets a row (zeros when it has no manifests or executions), once, in the\n  order requested, so the caller can zip it to its rows. More than 1000 distinct ids fails\n  the field with TRAX_TOO_MANY_IDS.\n  \"\"\"\n  stats(groupIds: [Long!]!): [ManifestGroupStats!]!\n\n  \"\"\"\n  Returns the dependency graph for the given group, or null if the group\n  does not exist. Empty groups still return a single-node graph (the focal group)\n  so the UI can render it.\n  \"\"\"\n  graph(groupId: Long!): ManifestGroupDependencyGraph\n\n  \"\"\"\n  The whole cross-group dependency graph: every group as a node and every cross-group\n  dependency as a directed parent → dependent edge. Nothing is highlighted. Backs the\n  dashboard's global dependency graph on the manifest-groups page.\n  \"\"\"\n  dependencyGraph: ManifestGroupDependencyGraph!\n}\n\n\"\"\"\nQueries over the log records trains write, for the dashboard's Logs page and ad-hoc API consumers.\nReads only; logs are written by the framework. The page and the filtered count come from\nIOperationsService, which the dashboard reads too, so both apply one filter.\n\"\"\"\ntype LogQueries {\n  \"\"\"\n  A page of log records written by trains, newest first unless order says otherwise.\n  Pass the previous page's nextCursor as afterId to page deeply in either order;\n  skip is ignored when afterId is set. Unfiltered, the total may be an estimate\n  (isEstimatedCount). Filtered by text, it counts at most 10,000 matches: past that it\n  reads 10,000 with isCountCapped true, a lower bound. Under any other filter it is\n  exact.\n  \"\"\"\n  logs(\n    \"\"\"\n    How many records to skip (negative is treated as 0; above 10,000 is refused with TRAX_SKIP_TOO_DEEP, so page deeper with afterId).\n    \"\"\"\n    skip: Int! = 0\n\n    \"\"\"The page size, clamped to 1 through 500.\"\"\"\n    take: Int! = 25\n\n    \"\"\"Only records written by this execution.\"\"\"\n    metadataId: Long\n\n    \"\"\"Only records at this level or above.\"\"\"\n    minimumLevel: LogLevel\n\n    \"\"\"Only records with exactly this logger category.\"\"\"\n    category: String\n\n    \"\"\"A keyset cursor: the page continues after this id in the chosen order.\"\"\"\n    afterId: Long\n\n    \"\"\"Only records whose message contains this text, ignoring case.\"\"\"\n    messageContains: String\n\n    \"\"\"Only records whose logger category contains this text, ignoring case.\"\"\"\n    categoryContains: String\n\n    \"\"\"Newest first (the default) or oldest first, as a run's log reads.\"\"\"\n    order: SortOrder! = NEWEST\n  ): PagedResultOfLogEntry!\n}\n\n\"\"\"\nQueries under operations.metrics. Backed entirely by\nIOperationsService so the dashboard's KPI cards / charts and the\nGraphQL API see identical numbers.\n\"\"\"\ntype MetricsQueries {\n  \"\"\"\n  The dashboard's headline counts, the executions-over-time chart for range, and the\n  seven-day top failures, slowest trains and throughput series: the same numbers the\n  dashboard's overview shows.\n  \"\"\"\n  dashboard(\n    \"\"\"The window and bucket size of the time series.\"\"\"\n    range: MetricsRange! = LAST24_HOURS\n\n    \"\"\"Leave the scheduler's own internal trains out of the counts.\"\"\"\n    hideAdminTrains: Boolean! = false\n  ): DashboardMetrics!\n\n  \"\"\"\n  Runtime metrics of this API process: start time, uptime, working set and managed heap\n  size, read when called. CPU is on serverCpuPercent.\n  \"\"\"\n  server: ServerMetrics!\n\n  \"\"\"\n  This API process's CPU utilisation since the previous poll (0-100, normalised by core\n  count). Separate from IOperationsService) because it is stateful per process: it needs\n  a delta between two samples, so the first poll returns null while the baseline primes.\n  \"\"\"\n  serverCpuPercent: Float\n}\n\n\"\"\"\nQueries under operations.config. Returns the live scheduler runtime settings;\nmatches what the dashboard's ServerSettingsPage reads, since both go through\nIOperationsService.\n\"\"\"\ntype ConfigQueries {\n  \"\"\"\n  The scheduler's current runtime settings, as this process holds them in memory (including\n  any change made with updateScheduler).\n  \"\"\"\n  scheduler: SchedulerConfigSnapshot!\n\n  \"\"\"\n  The API host's environment name (IHostEnvironment.EnvironmentName), which the\n  dashboard shows as its environment badge.\n  \"\"\"\n  environmentName: String!\n\n  \"\"\"\n  The version of Trax serving this API, such as 1.46.0: the Trax.Api.GraphQL\n  package's version without its build metadata. It is what the dashboard's footer shows for\n  the Trax.Dashboard package, and like it, it says which Trax release the host runs, not the\n  host application's own version.\n  \"\"\"\n  version: String!\n\n  \"\"\"\n  The level each category configured under the API host's Logging:LogLevel section\n  filters at now, Default first and the rest by name, including any change made with\n  setLogLevels. Read through ILogLevelService, the call the dashboard's\n  server settings make. Only that section is read; nothing else in configuration is reachable\n  from here. Empty when the host configures none.\n  \"\"\"\n  logLevels: [LogLevelSetting!]!\n}\n\n\"\"\"\nA train's declared chain as an immutable graph: every step it declares, with the types that flow\nthrough it, every track a routing step declares, and an id for each node that the steps of a run\nreport as they execute.\n\"\"\"\ntype ChainGraph {\n  \"\"\"The train's implementation type, by full name.\"\"\"\n  train: String!\n\n  \"\"\"The train's input type.\"\"\"\n  input: String!\n\n  \"\"\"The train's output type.\"\"\"\n  output: String!\n\n  \"\"\"The chain's steps, in the order it declares them.\"\"\"\n  nodes: [ChainGraphNode!]!\n\n  \"\"\"\n  Every step of the chain at any depth, in one list: depth first, each step before the steps on its tracks, each track's steps in declared order. Each says where it sits (parentId, track, depth), so a client can rebuild the tree without following nested tracks, which a query cannot follow past the server's field-cycle limit.\n  \"\"\"\n  allNodes: [DeclaredNode!]!\n\n  \"\"\"What the declaration did that no step can express.\"\"\"\n  refusals: [String!]!\n\n  \"\"\"\n  A hash of the graph's canonical JSON, as 64 lowercase hex digits. It changes when any step, type or track changes, so a client can tell a redeployed chain from the one it drew.\n  \"\"\"\n  hash: String!\n}\n\n\"\"\"\nOne run drawn on its train's declared chain: every node the train declares, each with the steps\nthe run recorded for it and where it stands, and the steps that match no node. Read through\nRunGraphs, which operations.runGraph and the dashboard's run page both call.\n\"\"\"\ntype RunGraph {\n  \"\"\"The run's id.\"\"\"\n  metadataId: Long!\n\n  \"\"\"The run's train, by its canonical name.\"\"\"\n  train: String!\n\n  \"\"\"\n  False when the host has no graph for the train (not registered here, or its chain cannot be read outside a request): nodes is empty and every step is unmatched.\n  \"\"\"\n  hasGraph: Boolean!\n\n  \"\"\"The graph's Hash, or null without a graph.\"\"\"\n  hash: String\n\n  \"\"\"The declared nodes, in the order the chain declares them.\"\"\"\n  nodes: [RunGraphNode!]!\n\n  \"\"\"\n  Every node of the graph at any depth, in one list: depth first, each node before the nodes on its tracks, each track's nodes in declared order. Each says where it sits (parentId, track, depth), so a client can rebuild the tree without following nested tracks, which a query cannot follow past the server's field-cycle limit. Select only the tracks' own fields here (name, taken, ...), not their nodes.\n  \"\"\"\n  allNodes: [RunGraphNode!]!\n\n  \"\"\"\n  Steps that match no node of the current graph: recorded before node ids were, on a withheld track, or for a chain that has changed since the run.\n  \"\"\"\n  unmatchedSteps: [JunctionStep!]!\n\n  \"\"\"\n  True when the run recorded more steps than one read matches (500), so a later node can show as not reached when it ran.\n  \"\"\"\n  moreSteps: Boolean!\n\n  \"\"\"\n  True when resumeExecution without from can resume the run after its latest checkpoint: it failed or was cancelled, no state machine's step started it, and the resume check over the declared chain allows it. The mutation can still refuse the run for its saved input or a resume already queued.\n  \"\"\"\n  canResume: Boolean!\n}\n\n\"\"\"\nScheduler management mutations: trigger, disable, enable, and cancel manifests and groups.\nAlso exposes the nested deadLetters namespace.\n\"\"\"\ntype OperationsMutations {\n  \"\"\"\n  Nested namespace exposing dead letter mutations (requeue, acknowledge, batch ops).\n  \"\"\"\n  deadLetters: DeadLetterMutations!\n\n  \"\"\"\n  Nested namespace exposing work queue mutations (queue a train, cancel queued entries).\n  \"\"\"\n  workQueue: WorkQueueMutations!\n\n  \"\"\"\n  Nested namespace exposing manifest group mutations (updateManifestGroup).\n  \"\"\"\n  manifestGroups: ManifestGroupMutations!\n\n  \"\"\"\n  Nested namespace exposing scheduler config mutations (updateScheduler).\n  \"\"\"\n  config: ConfigMutations!\n\n  \"\"\"\n  Queues an immediate run of the manifest with this external id, outside its normal schedule,\n  which continues unaffected. A manifest holds at most one queued entry, so when it already has\n  one, that entry is brought forward to now instead of a second one being queued. When that\n  entry is a retry, askAfresh: true makes it ask its deciders again instead of replaying\n  the failed run's decisions; if the dispatcher had already claimed the retry, it is too late to\n  change: the mutation still succeeds, and its message says the run replays the failed run's\n  decisions. The message says which happened (a new run queued, a queued one brought forward,\n  or one already due released as the trigger) and id is that work queue entry. Through\n  CancellationToken), the call the dashboard's Trigger\n  buttons make. An unknown external id, or a host with no database provider, where nothing\n  dispatches the queue, returns success: false and changes nothing.\n  \"\"\"\n  triggerManifest(externalId: String!, askAfresh: Boolean! = false): OperationResponse!\n\n  \"\"\"\n  Queues a run of the manifest with this external id that becomes eligible for dispatch once\n  delay has passed (an ISO-8601 duration such as PT5M). The normal schedule\n  continues unaffected. When the manifest already has a queued entry, no second one is\n  queued: that entry keeps its time if it is due sooner, and is brought forward to\n  now + delay otherwise. With askAfresh: true a queued retry the trigger\n  releases asks its deciders again instead of replaying the failed run's decisions; as with\n  triggerManifest, the message says so when the dispatcher had already claimed it and it\n  still replays. As with triggerManifest, the message says which happened and id\n  is the entry. An unknown external id, or a host where nothing dispatches the queue, returns\n  success: false and changes nothing.\n  \"\"\"\n  triggerManifestDelayed(externalId: String!, delay: Duration!, askAfresh: Boolean! = false): OperationResponse!\n\n  \"\"\"\n  Disables the manifest with this external id so the scheduler stops running it. The manifest\n  is kept; enableManifest turns it back on. An unknown external id returns\n  success: false and changes nothing.\n  \"\"\"\n  disableManifest(externalId: String!): OperationResponse!\n\n  \"\"\"\n  Enables the manifest with this external id so the scheduler runs it again. An unknown\n  external id returns success: false and changes nothing.\n  \"\"\"\n  enableManifest(externalId: String!): OperationResponse!\n\n  \"\"\"\n  Requests cancellation of every pending and running execution of the manifest with this\n  external id. A running train stops at its next junction boundary and ends Cancelled, and is\n  not retried. count is the number of executions flagged. An unknown external id\n  returns success: false and changes nothing.\n  \"\"\"\n  cancelManifest(externalId: String!): OperationResponse!\n\n  \"\"\"\n  Queues an immediate run of every enabled manifest in the group that can run on its own.\n  Dependent manifests are skipped, since they run after their parent. count is the number\n  of manifests a new run was queued for; the message also counts the ones that already had a\n  queued run, which now runs as the trigger. Through\n  CancellationToken), the call the dashboard's group\n  Trigger makes. A host where nothing dispatches the queue returns success: false.\n  \"\"\"\n  triggerGroup(groupId: Long!): OperationResponse!\n\n  \"\"\"\n  Requests cancellation of every pending and running execution of every manifest in the group.\n  count is the number of executions flagged.\n  \"\"\"\n  cancelGroup(groupId: Long!): OperationResponse!\n\n  \"\"\"\n  Triggers the listed manifests by id, each as triggerManifest triggers one: an\n  immediate run is queued, or the manifest's queued entry is brought forward to now when it\n  already has one. Through CancellationToken), the call the\n  dashboard's Trigger Selected makes. With askAfresh: true a queued retry the trigger\n  releases asks its deciders again instead of replaying the failed run's decisions; one the\n  dispatcher had already claimed still replays, and is counted in tooLateToAskAfresh\n  with a note. Unknown ids are skipped and noted without stopping the rest. An empty list, or\n  more than 1000 ids, returns success: false and triggers nothing.\n  \"\"\"\n  triggerManifests(ids: [Long!]!, askAfresh: Boolean! = false): BatchTriggerResponse!\n\n  \"\"\"\n  Triggers every listed manifest group by id, each as triggerGroup triggers one: every\n  enabled member that runs on its own schedule is triggered, and dependent members are left to\n  run after their parent. Through CancellationToken),\n  the call the dashboard's Trigger Selected on the groups page makes. The counts are of\n  manifests, except matched and skipped, which count group ids. An empty list,\n  or more than 1000 ids, returns success: false and triggers nothing.\n  \"\"\"\n  triggerGroups(ids: [Long!]!): BatchTriggerResponse!\n\n  \"\"\"\n  Requests cancellation of every pending and running execution of every manifest in the\n  listed groups, as cancelGroup does for one, through\n  CancellationToken), the call the dashboard's Cancel\n  Running makes. count is the number of executions flagged, zero included. An empty\n  list, or more than 1000 ids, returns success: false and flags nothing.\n  \"\"\"\n  cancelGroups(ids: [Long!]!): OperationResponse!\n\n  \"\"\"\n  Requests cancellation of a single execution by id, when it is still pending or in\n  progress. The request is durable: the process running the train sees it and ends the run\n  as Cancelled, and a run on this host is cancelled at once. count is 1 when the\n  execution was flagged; an execution that is already finished or does not exist returns\n  success: false with count 0. So does a run a step of a user's state-machine\n  draft started, with the reason: a user's draft is read-only to operators, and only its user\n  cancels the run, by leaving the state (central ADR 0046).\n  \"\"\"\n  cancelExecution(id: Long!): OperationResponse!\n\n  \"\"\"\n  Requests cancellation of the listed executions, as cancelExecution does for one:\n  every one still pending or in progress is flagged, and finished or unknown ids are skipped.\n  A run a step of a user's state-machine draft started is skipped too, and the message says\n  how many and why. count is the number flagged, zero included. An empty list, or more\n  than 1000 ids, returns success: false and flags nothing.\n  \"\"\"\n  cancelExecutions(ids: [Long!]!): OperationResponse!\n\n  \"\"\"\n  Enables or disables the listed manifests by id. Only manifests whose flag differs are\n  written; count is the number changed, zero included. An empty list, or more than\n  1000 ids, returns success: false and changes nothing.\n  \"\"\"\n  setManifestsEnabled(ids: [Long!]!, enabled: Boolean!): OperationResponse!\n\n  \"\"\"\n  Sets whether retries of the listed manifests replay the decisions of the run they retry\n  (replayDecisionsOnRetry). Only manifests whose flag differs are written; count\n  is the number changed, zero included. Turning it off also clears the replay link of each\n  manifest's queued entry, so a retry waiting out its backoff asks afresh. An empty list, or\n  more than 1000 ids, returns success: false and changes nothing.\n  \"\"\"\n  setManifestsReplayDecisionsOnRetry(ids: [Long!]!, replay: Boolean!): OperationResponse!\n\n  \"\"\"\n  Re-queues an execution: queues a fresh run of the same train with the input the execution\n  recorded, through CancellationToken), the same call the\n  dashboard's Re-queue button makes. Fails without queueing when the execution does not exist,\n  recorded no input, recorded a placeholder in place of its input (too large, unserializable\n  or disposed), or recorded an input with [TraxSensitive] members masked. When the\n  execution recorded decisions, the new run replays them, so it takes the tracks the\n  execution took; with askAfresh: true it asks its deciders again instead. When a\n  queued entry or a run already replays that execution, the new run is queued afresh either\n  way, and the message says so.\n  \"\"\"\n  requeueExecution(id: Long!, askAfresh: Boolean! = false): OperationResponse!\n\n  \"\"\"\n  Resumes a failed or cancelled execution from a checkpoint instead of running every step\n  again: queues a run of the same train, with the input the execution recorded, that skips\n  to the step from names (a node id, as runGraph gives it), or to the step after\n  the execution's latest checkpoint when from is omitted. Through\n  CancellationToken), the same call the dashboard's Resume\n  and Resume from here buttons make. It is a requeue in every check but where the run starts,\n  so it enqueues through the mediator and the train's [TraxAuthorize] applies, and the\n  new run replays the execution's decisions. Fails without queueing, with the reason, when\n  the execution does not exist, is not failed or cancelled, was started by a state machine's\n  step, has a saved input a requeue would refuse, already has a queued resume, or when no\n  checkpoint it wrote lets it resume at that step.\n  \"\"\"\n  resumeExecution(\n    \"\"\"The execution (metadata) id.\"\"\"\n    id: Long!\n\n    \"\"\"\n    The node id of the step to resume at, or null for after the latest checkpoint.\n    \"\"\"\n    from: String\n  ): OperationResponse!\n\n  \"\"\"\n  Patches mutable settings on a single manifest (enabled, retries, priority, timeout,\n  schedule). Each field on input is independent; null leaves it\n  unchanged. See UpdateManifestInput for the clear-timeout semantics.\n  A value the scheduler could not use returns success: false with the reason and saves\n  nothing: a timeout or interval that is not positive, a negative retry count, a priority\n  outside 0 to 31, a cron expression the scheduler cannot parse or that never fires, a switch\n  to CRON without an expression, a switch to INTERVAL without an interval, and a\n  switch to ONCE, DEPENDENT or DORMANT_DEPENDENT, which need a time or a\n  parent this input cannot give. The schedule is checked only when the input changes it. Through\n  CancellationToken), which runs every check.\n  \"\"\"\n  updateManifest(id: Long!, input: UpdateManifestInput!): OperationResponse!\n\n  \"\"\"\n  Turns the observational effect whose factory has this full type name on or off in THIS\n  process, through Boolean), the call the\n  dashboard's effects page makes. The change is in memory: it does not reach the scheduler or\n  worker processes where trains usually run, and a restart restores the configured state. An\n  effect the registry does not track, or tracks as not toggleable, is refused and nothing\n  changes, as is any effect when the host registers no effect registry. On success\n  count is 1.\n  \"\"\"\n  setEffectEnabled(fullName: String!, enabled: Boolean!): OperationResponse!\n\n  \"\"\"\n  Writes settings of the configurable effect whose factory has this full type name, in THIS\n  process, through String}), the call the\n  dashboard's Configure dialog makes. Send only the settings you change: one not listed is\n  not written. It is all or nothing: every value is read as its setting's type and checked\n  against the setting's validation before any is written, and nothing is written when one is\n  refused; errors then says why, setting by setting. A sensitive setting can be\n  written though it is never read back. A setting listed twice, an empty list, or more than\n  1000 entries is refused. The change is in memory and applies to the next run in this\n  process; it does not reach the scheduler or worker processes where trains usually run, and\n  a restart restores the configured settings.\n  \"\"\"\n  configureEffect(\n    \"\"\"The effect factory's full type name, as effects lists it.\"\"\"\n    fullName: String!\n\n    \"\"\"The settings to write, by name, as text.\"\"\"\n    values: [EffectSettingValueInput!]!\n  ): ConfigureEffectResponse!\n\n  \"\"\"\n  Cancels a system-owned state-machine instance's live train run, and the instance then\n  moves through its state's OnCancelled edge. A run still queued is cancelled before\n  it starts and, when this host registers the machine, the instance moves in this call\n  (outcome: MOVED, state the state it entered); otherwise a host that does\n  moves it (RUN_CANCELLED). A dispatched run has its cancel requested: it stops at its\n  next junction and the instance moves when it ends (CANCEL_REQUESTED). Refused with\n  success: false and a typed outcome, changing nothing: a user-owned instance\n  (USER_OWNED; operators see users' drafts read-only), no such system instance\n  (NOT_FOUND), a state that waits on no run (NO_LIVE_RUN), and a run that has\n  already ended (RUN_ENDED). The message is the dashboard's, word for word.\n  \"\"\"\n  cancelMachineInstance(\n    \"\"\"The machine's id.\"\"\"\n    machine: String!\n\n    \"\"\"Who owns the instance; only SYSTEM can be cancelled.\"\"\"\n    ownerKind: SnapshotOwnerKind!\n\n    \"\"\"The instance id.\"\"\"\n    id: UUID!\n  ): MachineInstanceCancelResponse!\n\n  \"\"\"\n  Nested namespace exposing persisted-operation mutations (upload,\n  deactivate, restore). Open as far as its parent is, as on the query side.\n  \"\"\"\n  persistedOperations: PersistedOperationMutations!\n}\n\n\"\"\"\nDead letter management mutations: requeue, acknowledge, and batch operations.\n\"\"\"\ntype DeadLetterMutations {\n  \"\"\"\n  Queues a new run for one dead letter's manifest and marks the dead letter retried. Only a dead\n  letter awaiting intervention can be requeued, and a manifest holds one queued entry at a time:\n  if it already has one, the result reports failure and the dead letter stays awaiting intervention.\n  The new run replays the decisions of the manifest's failed run when that is sound, as a retry\n  does; askAfresh: true makes it ask its deciders again.\n  \"\"\"\n  requeueDeadLetter(id: Long!, askAfresh: Boolean! = false): DeadLetterOperationResult!\n\n  \"\"\"\n  Marks one dead letter acknowledged without running it again, recording note as the\n  reason. A note longer than 1,000 characters is refused by the scheduler and nothing changes.\n  \"\"\"\n  acknowledgeDeadLetter(id: Long!, note: String!): DeadLetterOperationResult!\n\n  \"\"\"\n  Requeues the listed dead letters. At most one work queue entry is created per manifest: dead\n  letters that share a manifest are folded into one entry and all resolved, and a dead letter\n  whose manifest already has a queued entry is skipped and left awaiting intervention.\n  askAfresh: true makes every new run ask its deciders again rather than replay.\n  \"\"\"\n  requeueDeadLetters(ids: [Long!]!, askAfresh: Boolean! = false): BatchDeadLetterResult!\n\n  \"\"\"\n  Marks the listed dead letters acknowledged without running them again, recording note\n  on each. A note longer than 1,000 characters is refused: count is 0 and nothing changes.\n  \"\"\"\n  acknowledgeDeadLetters(ids: [Long!]!, note: String!): BatchDeadLetterResult!\n\n  \"\"\"\n  Starts requeueing every dead letter awaiting intervention, creating at most one work queue\n  entry per manifest as requeueDeadLetters does, and returns at once with the job's\n  handle rather than holding the request for the whole backlog. Read\n  operations.deadLetters.requeueAllJob(id) on the same node until its status is no\n  longer RUNNING. The fold is not tied to this request: it finishes after the client\n  goes away, and only the node shutting down stops it. While one is running on this node,\n  this returns that one with started: false. askAfresh: true makes every new run\n  ask its deciders again rather than replay.\n  \"\"\"\n  requeueAllDeadLetters(askAfresh: Boolean! = false): DeadLetterRequeueJob!\n\n  \"\"\"\n  Marks every dead letter awaiting intervention acknowledged, recording note on each. A\n  note longer than 1,000 characters is refused: count is 0 and nothing changes.\n  \"\"\"\n  acknowledgeAllDeadLetters(note: String!): BatchDeadLetterResult!\n}\n\n\"\"\"\nMutations for the work queue: queue a train for execution, run one now, and cancel queued entries.\nThin wrappers around IOperationsService, which the dashboard also calls. Both\nshare validation and the enqueue path; the train's own authorization applies here, while the\ndashboard enqueues as the admin surface its host gates (see docs/0017).\n\"\"\"\ntype WorkQueueMutations {\n  \"\"\"Creates a new work queue entry that the dispatcher will pick up.\"\"\"\n  queueTrain(input: QueueTrainInput!): OperationResponse!\n\n  \"\"\"\n  Runs a train now, through the same CancellationToken) call as\n  the dashboard's Run dialog: its Pending execution row is written and handed to the job\n  submitter the train is routed to, skipping the work queue. The train's own authorization\n  applies, as for CancellationToken).\n  \"\"\"\n  runTrain(input: RunTrainInput!): OperationResponse!\n\n  \"\"\"\n  Cancels a queued work queue entry. Only entries with status Queued can be\n  cancelled, and not one a step of a user's state-machine draft queued: a user's draft is\n  read-only to operators, and only its user cancels the run, by leaving the state (central\n  ADR 0046).\n  \"\"\"\n  cancelWorkQueueEntry(id: Long!): OperationResponse!\n\n  \"\"\"\n  Cancels many queued entries in one statement. Only entries still in Queued are\n  affected; already-dispatched or cancelled ids are skipped, and so are entries a step of a\n  user's state-machine draft queued, which the message counts and explains. count is\n  the number actually cancelled, zero included. An empty list, or more than 1000 ids, returns\n  success: false and cancels nothing.\n  \"\"\"\n  cancelWorkQueueEntries(ids: [Long!]!): OperationResponse!\n}\n\n\"\"\"\nMutations under operations.manifestGroups. Patches mutable fields on a manifest\ngroup (max active jobs, priority, enabled) and enables or disables groups in bulk. Thin wrapper around\nCancellationToken) so the dashboard and API\nshare validation and persistence.\n\"\"\"\ntype ManifestGroupMutations {\n  \"\"\"\n  Patches mutable settings on a manifest group. Each field on input\n  is independent; passing null leaves a field unchanged.\n  \"\"\"\n  updateManifestGroup(id: Long!, input: UpdateManifestGroupInput!): OperationResponse!\n\n  \"\"\"\n  Enables or disables the listed manifest groups by id. Only groups whose flag differs are\n  written, with updatedAt bumped; count is the number changed, zero included.\n  An empty list, or more than 1000 ids, returns success: false and changes nothing.\n  \"\"\"\n  setManifestGroupsEnabled(ids: [Long!]!, enabled: Boolean!): OperationResponse!\n\n  \"\"\"\n  Enables or disables every manifest group. A field of its own so that \"all\" is never what an\n  empty or missing list means. count is the number changed, zero included.\n  \"\"\"\n  setAllManifestGroupsEnabled(enabled: Boolean!): OperationResponse!\n}\n\n\"\"\"\nMutations under operations.config. Patches mutable scheduler runtime\nsettings; the same service powers the dashboard's ServerSettingsPage save action.\n\"\"\"\ntype ConfigMutations {\n  \"\"\"\n  Changes the scheduler's runtime settings. Only the fields you set change; the rest keep their\n  current values. The change takes effect at once in this process and is saved so it\n  survives a restart. On success count is the number of fields that changed. A value\n  outside the range the scheduler can run with refuses the whole patch: the result reports\n  failure, names each offending field, and nothing is applied.\n  \"\"\"\n  updateScheduler(input: UpdateSchedulerConfigInput!): OperationResponse!\n\n  \"\"\"\n  Sets the level each listed log category filters at in THIS process, through\n  ILogLevelService, the call the dashboard's server settings make. Only a\n  category configured under Logging:LogLevel (or changed here before) can be set; a\n  list naming any other, an empty list, or more than 1000 entries is refused whole and\n  nothing changes. When a category is listed twice, the last level wins. The change lasts\n  until the process restarts and does not reach the other processes of the deployment.\n  notApplied lists categories whose loggers still filter at another level, which\n  happens when the host sets the filter itself after Trax.\n  \"\"\"\n  setLogLevels(\n    \"\"\"The categories to set, and their levels.\"\"\"\n    levels: [LogLevelSettingInput!]!\n  ): SetLogLevelsResponse!\n}\n\n\"\"\"The `Any` scalar type represents any valid GraphQL value.\"\"\"\nscalar Any\n\n\"\"\"One declared step of a ChainGraph.\"\"\"\ntype ChainGraphNode {\n  \"\"\"\n  The node's id, unique within its graph. It names the step and the routing step and track it sits in, and is what a recorded step's nodeId refers to.\n  \"\"\"\n  id: String!\n\n  \"\"\"Which chain primitive declared the step.\"\"\"\n  kind: ChainStepKind!\n\n  \"\"\"The junction or decider type, or null for a step that names none.\"\"\"\n  junction: String\n\n  \"\"\"The type the step consumes from Memory, or null.\"\"\"\n  in: String\n\n  \"\"\"The type the step contributes to Memory, or null.\"\"\"\n  out: String\n\n  \"\"\"True when what runs is decided only at run time.\"\"\"\n  opaque: Boolean!\n\n  \"\"\"\n  A routing step's tracks, of which a run takes one, or a PARALLEL step's branches, which all run side by side. Empty for any other step.\n  \"\"\"\n  tracks: [ChainGraphTrack!]!\n}\n\n\"\"\"\nOne step of a train's declared chain with where it sits, as declaredChain.allNodes lists every step at any depth. A client rebuilds the tree from each step's parentId and track.\n\"\"\"\ntype DeclaredNode {\n  \"\"\"The node's id, as ChainGraphNode.id.\"\"\"\n  id: String!\n  kind: ChainStepKind!\n  junction: String\n  in: String\n  out: String\n\n  \"\"\"True when what runs is decided only at run time.\"\"\"\n  opaque: Boolean!\n\n  \"\"\"\n  The id of the routing or PARALLEL step whose track this node sits on, or null at the chain's top level.\n  \"\"\"\n  parentId: String\n\n  \"\"\"\n  The name of the track or branch this node sits on, or null at the chain's top level.\n  \"\"\"\n  track: String\n\n  \"\"\"How many tracks deep the node sits: 0 at the chain's top level.\"\"\"\n  depth: Int!\n\n  \"\"\"\n  A routing step's tracks or a PARALLEL step's branches, in declared order, without their nodes: the nodes on each are the entries of allNodes whose parentId is this node's id and whose track is its name.\n  \"\"\"\n  tracks: [DeclaredTrack!]!\n}\n\n\"\"\"One declared node of a RunGraph, with what the run did there.\"\"\"\ntype RunGraphNode {\n  \"\"\"The node's id; see ChainGraph.\"\"\"\n  id: String!\n\n  \"\"\"Which chain primitive declared the step.\"\"\"\n  kind: ChainStepKind!\n\n  \"\"\"The junction or decider type, or null for a step that names none.\"\"\"\n  junction: String\n\n  \"\"\"The type the step consumes from Memory, or null.\"\"\"\n  in: String\n\n  \"\"\"The type the step contributes to Memory, or null.\"\"\"\n  out: String\n\n  \"\"\"True when what runs is decided only at run time (Opaque).\"\"\"\n  opaque: Boolean!\n\n  \"\"\"\n  Where the node stands in this run. A PARALLEL step records nothing itself: it is FAILED when any branch failed, CANCELLED when one was stopped, IN_PROGRESS while any branch is still going, down the tracks its routing steps took, and COMPLETED once every branch has finished. A CHECKPOINT is COMPLETED once the run stored it. In a resumed run, a node before the point it resumed at is RESTORED: the run skipped it. Once the run has ended, a step whose end was never recorded (the host stopped mid-junction, or the end event was dropped) is INTERRUPTED, never IN_PROGRESS.\n  \"\"\"\n  state: RunNodeState!\n\n  \"\"\"\n  The id of the routing or PARALLEL step whose track this node sits on, or null at the chain's top level.\n  \"\"\"\n  parentId: String\n\n  \"\"\"\n  The name of the track or branch this node sits on, or null at the chain's top level.\n  \"\"\"\n  track: String\n\n  \"\"\"How many tracks deep the node sits: 0 at the chain's top level.\"\"\"\n  depth: Int!\n\n  \"\"\"\n  True when resumeExecution(id, from) can resume the run at this node: the run failed or was cancelled and a checkpoint before the node lets it run on what that checkpoint restores.\n  \"\"\"\n  canResume: Boolean!\n\n  \"\"\"\n  True when a checkpoint the run can resume from is stored at this node. Only that it exists: what it holds is never returned.\n  \"\"\"\n  checkpointed: Boolean!\n\n  \"\"\"True when an answer the node acted on came from an earlier run.\"\"\"\n  replayed: Boolean!\n\n  \"\"\"\n  The track a routing step took, or null when it took none or it cannot be told. Always null for a PARALLEL step, which runs every branch.\n  \"\"\"\n  trackTaken: String\n\n  \"\"\"The run's steps recorded for this node, in position order.\"\"\"\n  steps: [JunctionStep!]!\n\n  \"\"\"\n  A routing step's tracks, or a PARALLEL step's branches, in declared order. Empty for any other step.\n  \"\"\"\n  tracks: [RunGraphTrack!]!\n}\n\n\"\"\"Defines when a policy shall be executed.\"\"\"\nenum ApplyPolicy {\n  \"\"\"Before the resolver was executed.\"\"\"\n  BEFORE_RESOLVER\n\n  \"\"\"After the resolver was executed.\"\"\"\n  AFTER_RESOLVER\n\n  \"\"\"The policy is applied in the validation step before the execution.\"\"\"\n  VALIDATION\n}\n\n\"\"\"One track of a routing step in a ChainGraph.\"\"\"\ntype ChainGraphTrack {\n  \"\"\"The track's name: an enum member, Yes, No, Unsure or Otherwise.\"\"\"\n  name: String!\n\n  \"\"\"What the track is for, as offered to the decider.\"\"\"\n  description: String\n\n  \"\"\"True for the Otherwise or Unsure track.\"\"\"\n  isFallback: Boolean!\n\n  \"\"\"The track's steps, in declared order.\"\"\"\n  nodes: [ChainGraphNode!]!\n}\n\n\"\"\"The kind of step a train's junction chain declares.\"\"\"\nenum ChainStepKind {\n  \"\"\"A junction resolved by its concrete type.\"\"\"\n  CHAIN\n\n  \"\"\"A junction resolved from Memory by its interface type.\"\"\"\n  I_CHAIN\n\n  \"\"\"A junction that may end the chain early with the train's return value.\"\"\"\n  SHORT_CIRCUIT\n\n  \"\"\"A projection from one type in Memory to another.\"\"\"\n  EXTRACT\n\n  \"\"\"The terminal step that produces the train's result.\"\"\"\n  RESOLVE\n\n  \"\"\"\n  A value handed to the chain directly, by AddServices or by Extract given a\n  value, which puts its type into Memory without a junction producing it.\n  \"\"\"\n  SEED\n\n  \"\"\"\n  Asks a decider a question about a value in Memory and puts the typed decision in Memory.\n  The step's junction is the decider, its input the state and its output the decision. A\n  Decide asking several questions records one step per question.\n  \"\"\"\n  DECIDE\n\n  \"\"\"\n  Routes on a choice in Memory to one of several declared tracks, which\n  Int32) holds.\n  \"\"\"\n  SWITCH\n\n  \"\"\"\n  Routes on a yes/no probability in Memory to its Yes, No or Unsure track.\n  \"\"\"\n  GATE\n\n  \"\"\"Routes on a score in Memory to the track for the level it reaches.\"\"\"\n  SCALE\n\n  \"\"\"\n  Runs a fixed set of named branches side by side, each on its own copy of Memory, and\n  merges what they produce. Int32) holds the branches.\n  \"\"\"\n  PARALLEL\n\n  \"\"\"\n  Stores the state type in Memory the chain names, so a later run can resume after it. The\n  step's input is the state; it contributes nothing to Memory.\n  \"\"\"\n  CHECKPOINT\n}\n\n\"\"\"\nA track of a routing step, or a branch of a Parallel step, as a DeclaredNode\nnames it: its name and what it is for, without its nodes, which the flat list carries itself.\n\"\"\"\ntype DeclaredTrack {\n  \"\"\"The track's or branch's name.\"\"\"\n  name: String!\n\n  \"\"\"What the track is for, as offered to the decider; null for a branch.\"\"\"\n  description: String\n\n  \"\"\"True for the Otherwise or Unsure track; never for a branch.\"\"\"\n  isFallback: Boolean!\n}\n\n\"\"\"\nOne track of a routing node, or one branch of a Parallel node, in a RunGraph.\n\"\"\"\ntype RunGraphTrack {\n  \"\"\"The track's or branch's name.\"\"\"\n  name: String!\n\n  \"\"\"What the track is for, as offered to the decider; null for a branch.\"\"\"\n  description: String\n\n  \"\"\"True for the Otherwise or Unsure track; never for a branch.\"\"\"\n  isFallback: Boolean!\n\n  \"\"\"\n  True when the run took this track. Every branch of a PARALLEL step is taken once the step has started.\n  \"\"\"\n  taken: Boolean!\n\n  \"\"\"The track's nodes, in declared order.\"\"\"\n  nodes: [RunGraphNode!]!\n}\n\n\"\"\"\nRoot query type. Empty by default. Sub-namespaces are added dynamically:\n\n  operations — added by TraxGraphQLBuilder.ExposeOperationQueries().\n  discover — added by  when trains\n    annotated with [TraxQuery] or query-model registrations are present.\n\"\"\"\ntype RootQuery {\n  operations: OperationsQueries\n}\n\n\"\"\"\nRoot mutation type. Empty by default. Sub-namespaces are added dynamically:\n\n  operations — added by TraxGraphQLBuilder.ExposeOperationMutations().\n  dispatch — added by  when trains\n    annotated with [TraxMutation] are registered.\n\"\"\"\ntype RootMutation {\n  operations: OperationsMutations\n}\n\n\"\"\"\nGraphQL subscription root for real-time push. Carries per-train lifecycle events plus a\ncoalesced onDataChanged signal that admin UIs use to refetch a domain's view without\npolling. Clients connect via WebSocket at the GraphQL endpoint.\n\"\"\"\ntype LifecycleSubscriptions {\n  \"\"\"\n  Fires when a train you may see starts running. Pass externalId to receive only\n  the run with that external id, such as the one a queue mutation returned.\n  \"\"\"\n  onTrainStarted(\n    \"\"\"\n    Only the run with this external id (matched exactly); every run when omitted.\n    \"\"\"\n    externalId: String\n  ): TrainLifecycleEvent!\n\n  \"\"\"\n  Fires when a train you may see completes successfully. Pass externalId to receive only\n  the run with that external id, such as the one a queue mutation returned.\n  \"\"\"\n  onTrainCompleted(\n    \"\"\"\n    Only the run with this external id (matched exactly); every run when omitted.\n    \"\"\"\n    externalId: String\n  ): TrainLifecycleEvent!\n\n  \"\"\"\n  Fires when a train you may see fails. Pass externalId to receive only\n  the run with that external id, such as the one a queue mutation returned.\n  \"\"\"\n  onTrainFailed(\n    \"\"\"\n    Only the run with this external id (matched exactly); every run when omitted.\n    \"\"\"\n    externalId: String\n  ): TrainLifecycleEvent!\n\n  \"\"\"\n  Fires when a train you may see is cancelled. Pass externalId to receive only\n  the run with that external id, such as the one a queue mutation returned.\n  \"\"\"\n  onTrainCancelled(\n    \"\"\"\n    Only the run with this external id (matched exactly); every run when omitted.\n    \"\"\"\n    externalId: String\n  ): TrainLifecycleEvent!\n\n  \"\"\"\n  Fires on every state change of a train you may see, including the start, completion, failure\n  and cancellation that the other lifecycle subscriptions report individually. Pass\n  externalId to follow one run, such as the one a queue mutation returned.\n  \"\"\"\n  onTrainStateChanged(\n    \"\"\"\n    Only the run with this external id (matched exactly); every run when omitted.\n    \"\"\"\n    externalId: String\n  ): TrainLifecycleEvent!\n\n  \"\"\"\n  Fires for each step of the run metadataId: a junction starting, completing,\n  failing or being cancelled, a question a routing step asked, and the track it took. Only a\n  host that called AddJunctionEvents() publishes them, and you receive them exactly when\n  you would receive that run's train events. In the operations view, read\n  operations.junctionRuns for the steps a run took before you subscribed or that a gap\n  in sequence lost. A broadcast subscriber cannot read it, so it has no way to recover a\n  lost step: it sees only the steps that reach it after it subscribed.\n  \"\"\"\n  onJunctionEvent(\n    \"\"\"The run to follow (its execution id).\"\"\"\n    metadataId: Long!\n  ): JunctionEvent!\n\n  \"\"\"\n  Fires when a scheduler/admin data domain changes (work queue, dead letters, manifests,\n  manifest groups, scheduler config). One event per coalesced burst; the payload names the\n  domain so a client can refetch just that view.\n  \"\"\"\n  onDataChanged: DataChangedEvent!\n}\n\n\"\"\"The `Long` scalar type represents a signed 64-bit integer.\"\"\"\nscalar Long\n\n\"\"\"Represents the possible states of a train during its lifecycle.\"\"\"\nenum TrainState {\n  \"\"\"The train has been created but has not yet started execution.\"\"\"\n  PENDING\n\n  \"\"\"The train has successfully completed execution.\"\"\"\n  COMPLETED\n\n  \"\"\"\n  The train encountered an error during execution and did not complete successfully.\n  \"\"\"\n  FAILED\n\n  \"\"\"The train is currently executing.\"\"\"\n  IN_PROGRESS\n\n  \"\"\"The train was explicitly cancelled by an operator or system signal.\"\"\"\n  CANCELLED\n}\n\n\"\"\"\nThe `DateTime` scalar type represents a date and time with time zone offset information.\n\"\"\"\nscalar DateTime\n\n\"\"\"What happened to a step of a run.\"\"\"\nenum JunctionEventType {\n  \"\"\"A junction started.\"\"\"\n  JUNCTION_STARTED\n\n  \"\"\"A junction returned a result.\"\"\"\n  JUNCTION_COMPLETED\n\n  \"\"\"A junction failed.\"\"\"\n  JUNCTION_FAILED\n\n  \"\"\"A junction was stopped by a cancellation the run was asked for.\"\"\"\n  JUNCTION_CANCELLED\n\n  \"\"\"A routing step asked a question and the run acts on the answer.\"\"\"\n  DECIDED\n\n  \"\"\"A decider's answer the run would not act on; the routing step fails.\"\"\"\n  DECISION_REFUSED\n\n  \"\"\"A routing step sent the run down a track.\"\"\"\n  ROUTED\n}\n\n\"\"\"\nWhat one step of a run's timeline is: a junction that ran, a question a routing step asked, or\nthe track a routing step took. Carried by junction events and stored in\ntrax.junction_run.kind.\n\"\"\"\nenum JunctionRunKind {\n  \"\"\"An EffectJunction that ran.\"\"\"\n  JUNCTION\n\n  \"\"\"A question answered by choosing one of its options (Decide, Switch).\"\"\"\n  CHOICE\n\n  \"\"\"A question answered by a position on ordered levels (Scale).\"\"\"\n  SCORE\n\n  \"\"\"A question answered by the probability of yes (Gate).\"\"\"\n  YES_NO\n\n  \"\"\"The track a routing step sent the run down.\"\"\"\n  ROUTE\n}\n\n\"\"\"\nWhere one step of a run's timeline stands. Carried by junction events and stored in\ntrax.junction_run.state.\n\"\"\"\nenum JunctionRunState {\n  \"\"\"The junction has started and not yet returned.\"\"\"\n  IN_PROGRESS\n\n  \"\"\"\n  The junction returned a result, or the question was answered, or the track taken.\n  \"\"\"\n  COMPLETED\n\n  \"\"\"\n  The junction failed, or a decider's answer was refused and the routing step failed on it.\n  \"\"\"\n  FAILED\n\n  \"\"\"The junction stopped because the run was asked to cancel.\"\"\"\n  CANCELLED\n}\n\n\"\"\"\nWhat kind of failure a train hit, so a consumer can decide whether to retry, rebase, or give up\nwithout matching on exception messages at every call site.\n\"\"\"\nenum FailureClass {\n  \"\"\"\n  No classifier was registered, or it did not recognise this failure. Means \"decide as you\n  would have before this existed\" — the default, so behaviour is unchanged until something\n  deliberately acts on a classification.\n  \"\"\"\n  UNCLASSIFIED\n\n  \"\"\"\n  Expected to succeed if attempted again: a throttle, a lost connection, a server timeout\n  reported as an error.\n  \"\"\"\n  TRANSIENT\n\n  \"\"\"\n  Someone else changed the thing first. The work is valid but was built on a state that has\n  moved, so the answer is usually to rebuild against current state and try again, not to\n  compensate.\n  \"\"\"\n  CONFLICT\n\n  \"\"\"\n  Will fail the same way every time — a validation error, a missing record, a rejected\n  credential. Retrying is waste.\n  \"\"\"\n  PERMANENT\n}\n\n\"\"\"\nA point-in-time health summary of the Trax system, computed from the shared store on each\nrequest. Status is Degraded when any dead letter awaits intervention\nor more than 10 executions failed in the last hour, and Healthy otherwise.\n\"\"\"\ntype HealthStatus {\n  \"\"\"Healthy or Degraded.\"\"\"\n  status: String!\n\n  \"\"\"A one-line human-readable explanation of Status.\"\"\"\n  description: String!\n\n  \"\"\"How many work queue entries are queued and not yet dispatched.\"\"\"\n  queueDepth: Int!\n\n  \"\"\"How many executions are running now.\"\"\"\n  inProgress: Int!\n\n  \"\"\"How many executions failed with an end time in the last hour.\"\"\"\n  failedLastHour: Int!\n\n  \"\"\"How many dead letters await intervention.\"\"\"\n  deadLetters: Int!\n}\n\n\"\"\"\nA train available in the system, including its input schema for API consumers.\n\"\"\"\ntype TrainInfo {\n  serviceTypeName: String!\n  implementationTypeName: String!\n  inputTypeName: String!\n  outputTypeName: String!\n  lifetime: String!\n  inputSchema: [InputPropertySchema!]!\n  requiredPolicies: [String!]!\n  requiredRoles: [String!]!\n  isQuery: Boolean!\n  isMutation: Boolean!\n  graphQLName: String\n  isBroadcastEnabled: Boolean!\n\n  \"\"\"\n  The train's canonical name: its service interface's FullName, which every other\n  operations field that takes a train keys on (workQueue.queueTrain,\n  workQueue.runTrain, trainStats, executions(trainName:),\n  workQueues(trainName:)). ServiceTypeName is a friendly name for\n  display and is not accepted by those fields.\n  \"\"\"\n  fullName: String!\n\n  \"\"\"\n  Whether the train overrides QueueSubjectKey, so its queued runs for one subject run\n  one at a time (an override may still return no key for a given input). A run started with\n  workQueue.runTrain bypasses that serialization and may run alongside queued or\n  in-flight work for the same subject, which is what the dashboard's Run dialog warns about.\n  \"\"\"\n  hasQueueSubjectKey: Boolean!\n}\n\n\"\"\"\nA registered observational effect and its runtime state, as seen by THIS process. The effect\nregistry is an in-memory per-process singleton with no persistence or cross-process broadcast,\nso operations.setEffectEnabled changes this process only, not the scheduler or worker\nprocesses where trains usually run, and a restart restores the configured state. Backs the\ndashboard's effects list.\n\"\"\"\ntype EffectInfo {\n  \"\"\"The effect provider factory's type name.\"\"\"\n  name: String!\n\n  \"\"\"The effect provider factory's full type name, which identifies it.\"\"\"\n  fullName: String!\n\n  \"\"\"Whether the effect currently runs in this process.\"\"\"\n  enabled: Boolean!\n\n  \"\"\"\n  Whether the effect registry allows the effect to be enabled and disabled at runtime.\n  \"\"\"\n  toggleable: Boolean!\n\n  \"\"\"\n  Whether the effect's factory exposes runtime settings (it implements\n  IConfigurableProviderFactory).\n  \"\"\"\n  isConfigurable: Boolean!\n\n  \"\"\"The full name of the settings type, when configurable.\"\"\"\n  configurationTypeName: String\n\n  \"\"\"\n  The factory's current settings serialized as JSON, when configurable. Settings can hold\n  credentials, so this is only reachable through the operations namespace and its gate,\n  the same gate that guards an execution's input.\n  \"\"\"\n  configuration: String\n\n  \"\"\"\n  The settings of a configurable effect, one per public read-write property of its settings\n  type, editable ones first in declaration order; empty when the effect is not configurable.\n  operations.configureEffect writes them by Name. A\n  setting marked [TraxSensitive] never carries its value.\n  \"\"\"\n  fields: [EffectSettingInfo!]!\n}\n\n\"\"\"\nA page of one run's recorded decisions, in the order they were recorded.\n\"\"\"\ntype DecisionPage {\n  \"\"\"The decisions on this page.\"\"\"\n  items: [DecisionRecord!]!\n\n  \"\"\"The page size used, after clamping.\"\"\"\n  take: Int!\n\n  \"\"\"\n  The id of the last decision on the page, to pass as the next call's afterId; null when\n  the page is empty.\n  \"\"\"\n  nextCursor: Long\n}\n\n\"\"\"\nA single manifest schedule exclusion window, mirroring the domain Exclusion: a\nflat discriminated shape where Type selects which fields apply. DaysOfWeek is set\nfor DaysOfWeek, Dates for Dates, StartDate/EndDate for DateRange, and\nStartTime/EndTime for TimeWindow. Backs the exclusions panel on the manifest detail page.\n\"\"\"\ntype ManifestExclusion {\n  type: ExclusionType!\n  daysOfWeek: [DayOfWeek!]\n  dates: [LocalDate!]\n  startDate: LocalDate\n  endDate: LocalDate\n  startTime: LocalTime\n  endTime: LocalTime\n}\n\ntype PagedResultOfManifestSummary {\n  items: [ManifestSummary!]!\n  totalCount: Int!\n  skip: Int!\n  take: Int!\n  isEstimatedCount: Boolean!\n  nextCursor: Long\n  isCountCapped: Boolean!\n}\n\n\"\"\"Defines how a manifest should be scheduled for execution.\"\"\"\nenum ScheduleType {\n  \"\"\"The manifest can only be triggered manually via API or code.\"\"\"\n  NONE\n\n  \"\"\"The manifest runs on a schedule defined by a cron expression.\"\"\"\n  CRON\n\n  \"\"\"The manifest runs at a fixed interval.\"\"\"\n  INTERVAL\n\n  \"\"\"\n  The manifest is designed for bulk/batch operations triggered programmatically.\n  \"\"\"\n  ON_DEMAND\n\n  \"\"\"The manifest runs after a parent manifest completes successfully.\"\"\"\n  DEPENDENT\n\n  \"\"\"\n  The manifest is declared as a dependent but only fires when explicitly activated\n  at runtime by the parent train via IDormantDependentContext.\n  \"\"\"\n  DORMANT_DEPENDENT\n\n  \"\"\"\n  The manifest fires exactly once at a scheduled time, then auto-disables.\n  \"\"\"\n  ONCE\n}\n\n\"\"\"\nA manifest as the list and point reads return it. Carries no Properties: the train\ninput a manifest holds is on ManifestDetail alone, the way an execution's input\nis on ExecutionDetail and not on ExecutionSummary.\n\"\"\"\ntype ManifestSummary {\n  \"\"\"The manifest's database id.\"\"\"\n  id: Long!\n\n  \"\"\"The manifest's stable external id.\"\"\"\n  externalId: String!\n\n  \"\"\"The name of the train the manifest runs.\"\"\"\n  name: String!\n\n  \"\"\"Whether the scheduler will run the manifest.\"\"\"\n  isEnabled: Boolean!\n\n  \"\"\"How the manifest is scheduled.\"\"\"\n  scheduleType: ScheduleType!\n\n  \"\"\"The cron expression, for a cron-scheduled manifest.\"\"\"\n  cronExpression: String\n\n  \"\"\"The interval in seconds, for an interval-scheduled manifest.\"\"\"\n  intervalSeconds: Int\n\n  \"\"\"How many times a failed run is retried before it is dead-lettered.\"\"\"\n  maxRetries: Int!\n\n  \"\"\"The run timeout in seconds, or null for none.\"\"\"\n  timeoutSeconds: Int\n\n  \"\"\"When the manifest last ran successfully (UTC).\"\"\"\n  lastSuccessfulRun: DateTime\n\n  \"\"\"The id of the manifest group it belongs to.\"\"\"\n  manifestGroupId: Long!\n\n  \"\"\"The manifest this one runs after, for a dependent manifest.\"\"\"\n  dependsOnManifestId: Long\n\n  \"\"\"The dispatch priority of the work it queues.\"\"\"\n  priority: Int!\n\n  \"\"\"The name of the manifest group it belongs to.\"\"\"\n  manifestGroupName: String\n\n  \"\"\"\n  Whether a retry of the manifest's failed run (an automatic retry, or a requeue of its dead\n  letter) replays the decisions that run recorded rather than asking the decider again.\n  Set at scheduling with ScheduleOptions.ReplayDecisionsOnRetry, and afterwards with the\n  setManifestsReplayDecisionsOnRetry mutation (or the dashboard's matching action).\n  \"\"\"\n  replayDecisionsOnRetry: Boolean!\n}\n\n\"\"\"\nFull detail for a single manifest: everything ManifestSummary carries plus the\ntrain input it runs with (Properties) and the rest of its scheduling settings.\n\"\"\"\ntype ManifestDetail {\n  id: Long!\n  externalId: String!\n  name: String!\n  isEnabled: Boolean!\n  scheduleType: ScheduleType!\n  cronExpression: String\n  intervalSeconds: Int\n  maxRetries: Int!\n  timeoutSeconds: Int\n  lastSuccessfulRun: DateTime\n  manifestGroupId: Long!\n  manifestGroupName: String!\n  dependsOnManifestId: Long\n  priority: Int!\n  propertyTypeName: String\n  properties: String\n  misfirePolicy: MisfirePolicy!\n  misfireThresholdSeconds: Int\n  scheduledAt: DateTime\n  nextScheduledRun: DateTime\n  varianceSeconds: Int\n\n  \"\"\"\n  Whether a retry of the manifest's failed run (an automatic retry, or a requeue of its dead\n  letter) replays the decisions that run recorded rather than asking the decider again.\n  Set at scheduling with ScheduleOptions.ReplayDecisionsOnRetry, and afterwards with the\n  setManifestsReplayDecisionsOnRetry mutation (or the dashboard's matching action).\n  \"\"\"\n  replayDecisionsOnRetry: Boolean!\n}\n\n\"\"\"\nExecution roll-up for a single manifest: total run count broken down by state, plus the most\nrecent run and most recent successful run. Backs the summary cards on the dashboard's manifest\ndetail page.\n\"\"\"\ntype ManifestExecutionStats {\n  \"\"\"The manifest the counts are for.\"\"\"\n  manifestId: Long!\n\n  \"\"\"All of the manifest's executions, in any state.\"\"\"\n  total: Long!\n\n  \"\"\"Executions that completed.\"\"\"\n  completed: Long!\n\n  \"\"\"Executions that failed.\"\"\"\n  failed: Long!\n\n  \"\"\"Executions running now.\"\"\"\n  inProgress: Long!\n\n  \"\"\"Executions created but not yet started.\"\"\"\n  pending: Long!\n\n  \"\"\"Executions that were cancelled.\"\"\"\n  cancelled: Long!\n\n  \"\"\"When the most recent execution started (UTC), or null if it never ran.\"\"\"\n  lastRun: DateTime\n\n  \"\"\"\n  When the most recent completed execution ended (UTC), or null if none completed.\n  \"\"\"\n  lastSuccessfulRun: DateTime\n}\n\n\"\"\"\nExecution roll-up for a single train (by interface FullName): its runs broken down by state,\nmost recent and most recent successful run, and average completed duration. Backs the summary\ncards on the dashboard's per-train detail page. Keyed by the train interface's full name,\nthe name every execution records.\n\"\"\"\ntype TrainExecutionStats {\n  trainName: String!\n  total: Long!\n  completed: Long!\n  failed: Long!\n  inProgress: Long!\n  pending: Long!\n  cancelled: Long!\n  lastRun: DateTime\n  lastSuccessfulRun: DateTime\n  averageMilliseconds: Float\n}\n\n\"\"\"\nA process (host instance) that has executed trains, rolled up from the recorded executions by\nHostInstanceId. Backs the dashboard's cluster view, which answers \"which processes are\nrunning work, and are they still alive?\" across a split API + scheduler + worker deployment.\n\"\"\"\ntype HostInfo {\n  \"\"\"\n  The instance-level id of the process (for example an ECS task id, a pod name, or machine name plus process id), stable for the life of the process.\n  \"\"\"\n  instanceId: String!\n\n  \"\"\"Machine / container host name, if stamped.\"\"\"\n  name: String\n\n  \"\"\"\n  The kind of environment the process ran in (for example server, ecs, kubernetes or lambda), if stamped.\n  \"\"\"\n  environment: String\n\n  \"\"\"Most recent execution start on this host. The freshness signal.\"\"\"\n  lastSeen: DateTime!\n\n  \"\"\"Total executions attributed to this host.\"\"\"\n  totalExecutions: Long!\n\n  \"\"\"Executions on this host still in InProgress.\"\"\"\n  currentlyRunning: Int!\n}\n\ntype PagedResultOfExecutionSummary {\n  items: [ExecutionSummary!]!\n  totalCount: Int!\n  skip: Int!\n  take: Int!\n  isEstimatedCount: Boolean!\n  nextCursor: Long\n  isCountCapped: Boolean!\n}\n\n\"\"\"\nOrdering for paginated list reads. Both directions stay keyset-safe (they page on the\nmonotonic id index), so deep paging is O(page size) either way. Arbitrary-column\nsorting is intentionally not offered: it is incompatible with keyset pagination at\nmillions of rows (it forces OFFSET scans or a full sort), which the stress suite guards\nagainst. Filter to narrow the set instead.\n\"\"\"\nenum SortOrder {\n  \"\"\"Newest first (id descending). The default.\"\"\"\n  NEWEST\n\n  \"\"\"Oldest first (id ascending).\"\"\"\n  OLDEST\n}\n\n\"\"\"\nOne execution (a single run of a train) as the list and point reads return it. Carries no\ninput, output or stack trace: those are on ExecutionDetail, which the\nsingle-execution detail read returns.\n\"\"\"\ntype ExecutionSummary {\n  \"\"\"The execution's id.\"\"\"\n  id: Long!\n\n  \"\"\"The execution's stable external id.\"\"\"\n  externalId: String!\n\n  \"\"\"The name of the train that ran (the train interface's full name).\"\"\"\n  name: String!\n\n  \"\"\"The execution's current state.\"\"\"\n  trainState: TrainState!\n\n  \"\"\"When the execution started (UTC).\"\"\"\n  startTime: DateTime!\n\n  \"\"\"When the execution finished (UTC), or null while it is still running.\"\"\"\n  endTime: DateTime\n\n  \"\"\"The junction that failed, for a failed execution.\"\"\"\n  failureJunction: String\n\n  \"\"\"The failure message, for a failed execution.\"\"\"\n  failureReason: String\n\n  \"\"\"\n  The manifest that scheduled the execution, or null for a run not started by a manifest.\n  \"\"\"\n  manifestId: Long\n\n  \"\"\"Whether cancellation has been requested for the execution.\"\"\"\n  cancellationRequested: Boolean!\n\n  \"\"\"The machine name of the process that ran the execution, if recorded.\"\"\"\n  hostName: String\n\n  \"\"\"\n  The kind of environment that process ran in (for example server, ecs or lambda), if recorded.\n  \"\"\"\n  hostEnvironment: String\n\n  \"\"\"\n  The instance-level id of that process (for example an ECS task id or a pod name), if recorded.\n  \"\"\"\n  hostInstanceId: String\n\n  \"\"\"How the failure was classified, or Unclassified.\"\"\"\n  failureClass: FailureClass!\n\n  \"\"\"\n  The execution that started this one, for a run started from inside another train's run;\n  null otherwise. executionChildren lists a parent's runs the other way.\n  \"\"\"\n  parentId: Long\n\n  \"\"\"\n  The junction the execution is running now, while it is in progress; null otherwise.\n  \"\"\"\n  currentlyRunningJunction: String\n}\n\n\"\"\"\nFull detail for a single execution, including the input/output payloads and stack trace\nthat ExecutionSummary deliberately omits so paginated list reads stay lean.\nJunction-level context is limited to CurrentlyRunningJunction while the\nexecution runs and FailureJunction once it has failed.\n\"\"\"\ntype ExecutionDetail {\n  \"\"\"The execution's database id.\"\"\"\n  id: Long!\n\n  \"\"\"The execution's stable external id.\"\"\"\n  externalId: String!\n\n  \"\"\"The name of the train that ran.\"\"\"\n  name: String!\n\n  \"\"\"The execution's current state.\"\"\"\n  trainState: TrainState!\n\n  \"\"\"When the execution started (UTC).\"\"\"\n  startTime: DateTime!\n\n  \"\"\"When the execution finished (UTC), or null while it is still running.\"\"\"\n  endTime: DateTime\n\n  \"\"\"The junction that failed, for a failed execution.\"\"\"\n  failureJunction: String\n\n  \"\"\"The failure message, for a failed execution.\"\"\"\n  failureReason: String\n\n  \"\"\"The full name of the exception type that failed the execution.\"\"\"\n  failureException: String\n\n  \"\"\"The stack trace of the failure.\"\"\"\n  stackTrace: String\n\n  \"\"\"The serialized train input.\"\"\"\n  input: String\n\n  \"\"\"\n  The serialized train output, when the execution completed and recorded one.\n  \"\"\"\n  output: String\n\n  \"\"\"\n  The manifest that scheduled the execution, or null for a run not started by a manifest.\n  \"\"\"\n  manifestId: Long\n\n  \"\"\"Whether cancellation has been requested for the execution.\"\"\"\n  cancellationRequested: Boolean!\n\n  \"\"\"The junction running now, while the execution is in progress.\"\"\"\n  currentlyRunningJunction: String\n\n  \"\"\"When CurrentlyRunningJunction started (UTC).\"\"\"\n  junctionStartedAt: DateTime\n\n  \"\"\"The machine name of the process that ran the execution.\"\"\"\n  hostName: String\n\n  \"\"\"\n  The kind of environment the process ran in (for example server, ecs or lambda).\n  \"\"\"\n  hostEnvironment: String\n\n  \"\"\"\n  The instance-level id of the host (for example an ECS task id or a pod name).\n  \"\"\"\n  hostInstanceId: String\n\n  \"\"\"The number of executions this one started.\"\"\"\n  childCount: Int!\n\n  \"\"\"How the failure was classified, or Unclassified.\"\"\"\n  failureClass: FailureClass!\n\n  \"\"\"The execution that started this one, or null for a top-level run.\"\"\"\n  parentId: Long\n\n  \"\"\"When the run was due, for a scheduled run; null otherwise.\"\"\"\n  scheduledTime: DateTime\n\n  \"\"\"The project (entry assembly) of the process that ran it.\"\"\"\n  executor: String\n\n  \"\"\"The host's user-supplied labels as a JSON object, or null.\"\"\"\n  hostLabels: String\n\n  \"\"\"\n  The execution whose recorded decisions this one was queued to replay (a requeue, or a\n  manifest's retry that replays), as the dashboard's \"Replays Decisions Of\" shows it;\n  null for a run queued to ask its questions afresh.\n  \"\"\"\n  replayDecisionsOf: Long\n\n  \"\"\"\n  True when the execution was queued to replay the decisions of\n  ReplayDecisionsOf and asked its deciders afresh instead, because that replay\n  could not be honoured (the run it replays was not found, for one). False for a run that\n  replayed, or was never queued to.\n  \"\"\"\n  replayAbandoned: Boolean!\n\n  \"\"\"\n  The failed or cancelled execution this one resumed from a checkpoint, as the dashboard's\n  \"Resumes\" shows it; null for a run that ran from the top. See\n  Trax.Docs/adr/0047-a-checkpoint-stores-a-state-the-train-declares-and-a-resume-skips-to-it.md.\n  \"\"\"\n  resumeFrom: Long\n\n  \"\"\"\n  The step this execution resumed at, or null when it resumed after the latest\n  checkpoint of ResumeFrom (or did not resume).\n  \"\"\"\n  resumeAt: String\n}\n\ntype PagedResultOfMachineInstance {\n  items: [MachineInstance!]!\n  totalCount: Int!\n  skip: Int!\n  take: Int!\n  isEstimatedCount: Boolean!\n  nextCursor: Long\n  isCountCapped: Boolean!\n}\n\n\"\"\"\nWho owns a state-machine draft. Stored in trax.snapshot_draft.owner_kind.\n\"\"\"\nenum SnapshotOwnerKind {\n  \"\"\"\n  A user owns the draft. Its user_key names that user, and only that user's requests reach it.\n  \"\"\"\n  USER\n\n  \"\"\"\n  The system owns the instance. It has no user_key, it is created only from code, and no user\n  request reads, writes, lists or expires it.\n  \"\"\"\n  SYSTEM\n}\n\n\"\"\"\nOne state-machine instance read on its own, by operations.machineInstance. It has the\nlist item's fields and the runs the instance invoked, which only this lookup reads, so a page\nof instances never pays for a lookup per row.\n\"\"\"\ntype MachineInstanceDetail {\n  \"\"\"The row's key.\"\"\"\n  rowId: Long!\n\n  \"\"\"The machine's id.\"\"\"\n  machine: String!\n\n  \"\"\"Whether a user or the system owns the instance.\"\"\"\n  ownerKind: SnapshotOwnerKind!\n\n  \"\"\"The instance or draft id.\"\"\"\n  id: UUID!\n\n  \"\"\"The state it is in.\"\"\"\n  state: String!\n\n  \"\"\"The machine definition version it was last written under.\"\"\"\n  version: Int!\n\n  \"\"\"When it was created, or null for one written before Trax recorded it.\"\"\"\n  createdAt: DateTime\n\n  \"\"\"When it was last written.\"\"\"\n  updatedAt: DateTime!\n\n  \"\"\"True while its state waits on the outcome of a train run it invoked.\"\"\"\n  hasLiveInvokedRun: Boolean!\n\n  \"\"\"\n  The train runs the instance invoked, newest first, at most 50, with the one its state\n  waits on marked isLive. A user's draft lists only its live run.\n  \"\"\"\n  invokedRuns: [MachineInstanceInvokedRun!]!\n\n  \"\"\"True when the instance invoked more runs than InvokedRuns lists.\"\"\"\n  isInvokedRunsCapped: Boolean!\n\n  \"\"\"\n  The work queue entry of the run the state waits on while it is still queued, and so not\n  yet in InvokedRuns; null otherwise.\n  \"\"\"\n  queuedInvokedRunEntryId: Long\n}\n\n\"\"\"\nThe `UUID` scalar type represents a Universally Unique Identifier (UUID) as defined by RFC 9562.\n\"\"\"\nscalar UUID\n\n\"\"\"\nHow many instances of one machine are in one state, for one owner kind.\n\"\"\"\ntype MachineInstanceCount {\n  \"\"\"The machine's id.\"\"\"\n  machine: String!\n\n  \"\"\"The state.\"\"\"\n  state: String!\n\n  \"\"\"Who owns the instances counted.\"\"\"\n  ownerKind: SnapshotOwnerKind!\n\n  \"\"\"How many there are.\"\"\"\n  count: Long!\n}\n\ntype PagedResultOfDeadLetterSummary {\n  items: [DeadLetterSummary!]!\n  totalCount: Int!\n  skip: Int!\n  take: Int!\n  isEstimatedCount: Boolean!\n  nextCursor: Long\n  isCountCapped: Boolean!\n}\n\n\"\"\"Represents the resolution status of a dead-lettered job.\"\"\"\nenum DeadLetterStatus {\n  \"\"\"\n  The dead letter has not been addressed and requires manual intervention.\n  \"\"\"\n  AWAITING_INTERVENTION\n\n  \"\"\"The dead letter has been retried and a new execution was created.\"\"\"\n  RETRIED\n\n  \"\"\"The dead letter has been acknowledged by an operator without retrying.\"\"\"\n  ACKNOWLEDGED\n}\n\n\"\"\"\nA requeue of every dead letter awaiting intervention, running in the background on the node\nthat started it. requeueAllDeadLetters returns one at once, and\noperations.deadLetters.requeueAllJob(id) reads it again until Status is\nno longer Running.\n\"\"\"\ntype DeadLetterRequeueJob {\n  \"\"\"Identifies the job to requeueAllJob on the node that started it.\"\"\"\n  id: UUID!\n\n  \"\"\"Where the job is.\"\"\"\n  status: DeadLetterRequeueJobStatus!\n\n  \"\"\"How many dead letters were awaiting intervention when it started.\"\"\"\n  awaitingAtStart: Int!\n\n  \"\"\"When it started (UTC).\"\"\"\n  startedAt: DateTime!\n\n  \"\"\"When it stopped (UTC), or null while running.\"\"\"\n  finishedAt: DateTime\n\n  \"\"\"How many dead letters it requeued, once it has succeeded; null before.\"\"\"\n  count: Int\n\n  \"\"\"A human-readable description of where it is or how it ended.\"\"\"\n  message: String!\n\n  \"\"\"\n  false when a requeue-all was already running on this node, so no second one was\n  started and this is the one already running.\n  \"\"\"\n  started: Boolean!\n\n  \"\"\"\n  How many dead letters the job has requeued so far, updated as each page commits; with\n  AwaitingAtStart it says how far a running job has got. Once it has succeeded\n  it equals Count.\n  \"\"\"\n  processed: Int!\n}\n\n\"\"\"\nA dead letter: a manifest run that exhausted its retries and now waits for an operator to\nretry or acknowledge it. The scheduler never retries a dead letter on its own.\n\"\"\"\ntype DeadLetterSummary {\n  \"\"\"The dead letter's id, used by the retry and acknowledge mutations.\"\"\"\n  id: Long!\n\n  \"\"\"The id of the manifest whose run was dead-lettered.\"\"\"\n  manifestId: Long!\n\n  \"\"\"\n  The name of the train that manifest runs, or Unknown when the manifest can no longer be read.\n  \"\"\"\n  manifestName: String!\n\n  \"\"\"\n  Whether the dead letter still awaits intervention, was retried, or was acknowledged.\n  \"\"\"\n  status: DeadLetterStatus!\n\n  \"\"\"When the run was dead-lettered (UTC).\"\"\"\n  deadLetteredAt: DateTime!\n\n  \"\"\"Why the run was dead-lettered.\"\"\"\n  reason: String!\n\n  \"\"\"How many retries had been made when the run was dead-lettered.\"\"\"\n  retryCountAtDeadLetter: Int!\n\n  \"\"\"\n  When the dead letter was retried or acknowledged (UTC), or null while it awaits intervention.\n  \"\"\"\n  resolvedAt: DateTime\n\n  \"\"\"The note the operator left when resolving it, if any.\"\"\"\n  resolutionNote: String\n\n  \"\"\"\n  The id of the execution a retry started, once the dead letter has been retried.\n  \"\"\"\n  retryMetadataId: Long\n}\n\ntype PagedResultOfWorkQueueSummary {\n  items: [WorkQueueSummary!]!\n  totalCount: Int!\n  skip: Int!\n  take: Int!\n  isEstimatedCount: Boolean!\n  nextCursor: Long\n  isCountCapped: Boolean!\n}\n\n\"\"\"Represents the lifecycle status of a work queue entry.\"\"\"\nenum WorkQueueStatus {\n  \"\"\"The entry is waiting to be picked up by the JobDispatcher.\"\"\"\n  QUEUED\n\n  \"\"\"\n  The entry has been dispatched — a Metadata record was created and the job was enqueued.\n  \"\"\"\n  DISPATCHED\n\n  \"\"\"The entry was cancelled before dispatch.\"\"\"\n  CANCELLED\n}\n\n\"\"\"\nA work queue entry as the list reads return it: a request to run a train that waits to be\ndispatched. Carries no input; the single-entry detail read returns WorkQueueDetail\nwith it.\n\"\"\"\ntype WorkQueueSummary {\n  \"\"\"The entry's id.\"\"\"\n  id: Long!\n\n  \"\"\"The entry's stable external id.\"\"\"\n  externalId: String!\n\n  \"\"\"The name of the train the entry runs.\"\"\"\n  trainName: String!\n\n  \"\"\"The entry's status.\"\"\"\n  status: WorkQueueStatus!\n\n  \"\"\"When the entry was queued (UTC).\"\"\"\n  createdAt: DateTime!\n\n  \"\"\"When the entry was dispatched (UTC), or null while it is queued.\"\"\"\n  dispatchedAt: DateTime\n\n  \"\"\"\n  The earliest time the entry may be dispatched (UTC), for a delayed entry.\n  \"\"\"\n  scheduledAt: DateTime\n\n  \"\"\"The entry's dispatch priority.\"\"\"\n  priority: Int!\n\n  \"\"\"How many times dispatch has been attempted.\"\"\"\n  dispatchAttempts: Int!\n\n  \"\"\"The manifest that queued the entry, if any.\"\"\"\n  manifestId: Long\n\n  \"\"\"The execution the entry started, once dispatched.\"\"\"\n  metadataId: Long\n\n  \"\"\"The dead letter the entry was requeued from, if any.\"\"\"\n  deadLetterId: Long\n\n  \"\"\"The full name of the train input type.\"\"\"\n  inputTypeName: String\n\n  \"\"\"\n  When the entry became eligible for dispatch (UTC), or null while it is still being staged.\n  \"\"\"\n  confirmedAt: DateTime\n\n  \"\"\"The subject the entry serializes on, or null for none.\"\"\"\n  subjectKey: String\n\n  \"\"\"\n  The execution whose recorded decisions the run this entry starts will replay (a requeue,\n  or a manifest's retry that replays); null when it will ask its questions afresh.\n  \"\"\"\n  replayDecisionsOf: Long\n}\n\n\"\"\"\nFull detail for a single work queue entry: everything WorkQueueSummary carries,\nthe train input it was queued with, and what a queued entry with a subject is waiting on.\n\"\"\"\ntype WorkQueueDetail {\n  \"\"\"The entry's database id.\"\"\"\n  id: Long!\n\n  \"\"\"The entry's stable external id.\"\"\"\n  externalId: String!\n\n  \"\"\"The name of the train the entry runs.\"\"\"\n  trainName: String!\n\n  \"\"\"The entry's status.\"\"\"\n  status: WorkQueueStatus!\n\n  \"\"\"When the entry was queued (UTC).\"\"\"\n  createdAt: DateTime!\n\n  \"\"\"When the entry was dispatched (UTC), or null while it is queued.\"\"\"\n  dispatchedAt: DateTime\n\n  \"\"\"\n  The earliest time the entry may be dispatched (UTC), for a delayed entry.\n  \"\"\"\n  scheduledAt: DateTime\n\n  \"\"\"The entry's dispatch priority.\"\"\"\n  priority: Int!\n\n  \"\"\"How many times dispatch has been attempted.\"\"\"\n  dispatchAttempts: Int!\n\n  \"\"\"The manifest that queued the entry, if any.\"\"\"\n  manifestId: Long\n\n  \"\"\"The execution the entry started, once dispatched.\"\"\"\n  metadataId: Long\n\n  \"\"\"The dead letter the entry was requeued from, if any.\"\"\"\n  deadLetterId: Long\n\n  \"\"\"The full name of the train input type.\"\"\"\n  inputTypeName: String\n\n  \"\"\"\n  When the entry became eligible for dispatch (UTC), or null while it is still being staged.\n  \"\"\"\n  confirmedAt: DateTime\n\n  \"\"\"The subject the entry serializes on, or null for none.\"\"\"\n  subjectKey: String\n\n  \"\"\"The serialized train input.\"\"\"\n  input: String\n\n  \"\"\"\n  For a queued entry with a subject: the dispatched entry for the same subject whose run is\n  still pending or in progress. Dispatch skips the subject until that run finishes.\n  \"\"\"\n  subjectHeldBy: Long\n\n  \"\"\"\n  For a queued entry with a subject that nothing is holding: the queued entry for the same\n  subject that dispatch would offer first. Dispatch offers one entry per subject each cycle.\n  \"\"\"\n  subjectQueuedBehind: Long\n\n  \"\"\"\n  The execution whose recorded decisions the run this entry starts will replay (a requeue,\n  or a manifest's retry that replays); null when it will ask its questions afresh.\n  \"\"\"\n  replayDecisionsOf: Long\n}\n\ntype PagedResultOfManifestGroupSummary {\n  items: [ManifestGroupSummary!]!\n  totalCount: Int!\n  skip: Int!\n  take: Int!\n  isEstimatedCount: Boolean!\n  nextCursor: Long\n  isCountCapped: Boolean!\n}\n\n\"\"\"\nA manifest group: a named set of manifests that share a concurrency limit, a dispatch\npriority and an enabled switch.\n\"\"\"\ntype ManifestGroupSummary {\n  \"\"\"The group's id.\"\"\"\n  id: Long!\n\n  \"\"\"The group's unique name.\"\"\"\n  name: String!\n\n  \"\"\"\n  The most executions from this group that may run at once, or null for no per-group limit (only the global limit applies).\n  \"\"\"\n  maxActiveJobs: Int\n\n  \"\"\"\n  The group's dispatch priority, 0 to 31; work from a higher-priority group is dispatched first.\n  \"\"\"\n  priority: Int!\n\n  \"\"\"\n  Whether the group's manifests are eligible to be queued and dispatched.\n  \"\"\"\n  isEnabled: Boolean!\n\n  \"\"\"When the group was created (UTC).\"\"\"\n  createdAt: DateTime!\n\n  \"\"\"When the group was last changed (UTC).\"\"\"\n  updatedAt: DateTime!\n}\n\n\"\"\"\nExecution roll-up for a single manifest group: how many manifests it holds and its executions\nbroken down by state, plus the group's most recent run. Backs the per-group stat columns on the\ndashboard's manifest groups list. Fetched in a batch keyed by the visible page's group ids.\n\"\"\"\ntype ManifestGroupStats {\n  groupId: Long!\n  manifestCount: Long!\n  totalExecutions: Long!\n  completed: Long!\n  failed: Long!\n  inProgress: Long!\n  lastRun: DateTime\n}\n\n\"\"\"\n1-hop neighborhood of cross-group dependencies for a manifest group.\nReturned by CancellationToken) and\nconsumed by both the GraphQL operations.manifestGroups.graph query and the\ndashboard's dependency DAG visualisation.\n\"\"\"\ntype ManifestGroupDependencyGraph {\n  \"\"\"All groups in the neighborhood plus the focal group itself.\"\"\"\n  nodes: [DependencyGraphNode!]!\n\n  \"\"\"Directed edges between groups (parent → dependent).\"\"\"\n  edges: [DependencyGraphEdge!]!\n}\n\ntype PagedResultOfLogEntry {\n  items: [LogEntry!]!\n  totalCount: Int!\n  skip: Int!\n  take: Int!\n  isEstimatedCount: Boolean!\n  nextCursor: Long\n  isCountCapped: Boolean!\n}\n\nenum LogLevel {\n  TRACE\n  DEBUG\n  INFORMATION\n  WARNING\n  ERROR\n  CRITICAL\n  NONE\n}\n\n\"\"\"\nSnapshot of dashboard-relevant metrics. Returned by\nCancellationToken); consumed by the dashboard\nIndex page and the GraphQL operations.metrics.dashboard query.\n\"\"\"\ntype DashboardMetrics {\n  kpis: DashboardKpis!\n  executionsOverTime: [ExecutionsBucket!]!\n  topFailures: [TrainFailureCount!]!\n  topAverageDurations: [TrainAverageDuration!]!\n  throughputSeries: [ThroughputSeries!]!\n}\n\n\"\"\"\nSelects the granularity of the executions-over-time series in\nDashboardMetrics. The other series in the dashboard metrics block\n(throughput, top failures, avg durations) are always over the last 7 days.\n\"\"\"\nenum MetricsRange {\n  \"\"\"Last 60 minutes, 60 buckets, 1 minute each.\"\"\"\n  LAST60_MINUTES\n\n  \"\"\"Last 24 hours, 24 buckets, 1 hour each.\"\"\"\n  LAST24_HOURS\n}\n\n\"\"\"\nProcess-level health snapshot. Memory/GC/uptime are exact at call time; CPU%\nrequires consumer-side sampling state and is intentionally omitted from the shared\nservice.\n\"\"\"\ntype ServerMetrics {\n  \"\"\"When the host process started.\"\"\"\n  processStartTimeUtc: DateTime!\n\n  \"\"\"Seconds since process start.\"\"\"\n  uptimeSeconds: Float!\n\n  \"\"\"Resident set size (Process.WorkingSet64).\"\"\"\n  workingSetBytes: Long!\n\n  \"\"\"Total GC-managed heap (GC.GetTotalMemory(false)).\"\"\"\n  gcHeapBytes: Long!\n}\n\n\"\"\"\nSnapshot of the live scheduler runtime settings: the dashboard-editable subset of\nSchedulerConfiguration, LocalWorkerOptions, and\nMetadataCleanupConfiguration. Returned by\nGetSchedulerConfig; consumed by both the\ndashboard's ServerSettingsPage and the GraphQL operations.config.scheduler\nquery.\n\"\"\"\ntype SchedulerConfigSnapshot {\n  manifestManagerEnabled: Boolean!\n  jobDispatcherEnabled: Boolean!\n  manifestManagerPollingInterval: Duration!\n  jobDispatcherPollingInterval: Duration!\n  maxActiveJobs: Int\n  defaultMaxRetries: Int!\n  defaultRetryDelay: Duration!\n  retryBackoffMultiplier: Float!\n  maxRetryDelay: Duration!\n  defaultJobTimeout: Duration!\n  stalePendingTimeout: Duration!\n  recoverStuckJobsOnStartup: Boolean!\n  deadLetterRetentionPeriod: Duration!\n  autoPurgeDeadLetters: Boolean!\n  localWorkerCount: Int\n  metadataCleanupInterval: Duration\n  metadataCleanupRetention: Duration\n\n  \"\"\"\n  How far back a manifest's failed runs are counted toward its retry backoff and its dead\n  letter (SchedulerConfiguration.FailureCountWindow).\n  \"\"\"\n  failureCountWindow: Duration!\n}\n\n\"\"\"\nOne log category the host configures under Logging:LogLevel (or has changed at runtime),\nand the level its loggers filter at.\n\"\"\"\ntype LogLevelSetting {\n  \"\"\"The logging category, Default for the fallback.\"\"\"\n  category: String!\n\n  \"\"\"\n  The level the category's loggers filter at now, by its LogLevel name: a level\n  set at runtime when there is one, otherwise the configured one.\n  \"\"\"\n  level: String!\n\n  \"\"\"\n  The value configured under Logging:LogLevel, as written; null when the category is\n  not configured there.\n  \"\"\"\n  configuredLevel: String\n\n  \"\"\"\n  Whether a level was set at runtime with config.setLogLevels, so Level\n  is not the configured one. Lasts until the process restarts.\n  \"\"\"\n  overridden: Boolean!\n}\n\n\"\"\"\nThe result of an operations mutation. A mutation that could not do what was asked (the target\ndoes not exist, is in the wrong state, or the request was refused) returns\nSuccess = false with a Message rather than a GraphQL error. A failure of\nthe server itself, or a caller not allowed to run the train, is a GraphQL error instead.\n\"\"\"\ntype OperationResponse {\n  \"\"\"Whether the operation did what was asked.\"\"\"\n  success: Boolean!\n\n  \"\"\"\n  How many items the operation affected, for operations that act on a set; null otherwise.\n  \"\"\"\n  count: Int\n\n  \"\"\"A human-readable description of the outcome.\"\"\"\n  message: String\n\n  \"\"\"\n  The id of the one row the operation acted on, when there is one: the work queue entry\n  queueTrain and requeueExecution created, the execution (metadata) id\n  runTrain started, the work queue entry a manifest trigger queued or released, or the\n  manifest or group updateManifest or updateManifestGroup patched. null\n  otherwise, and on a failure that touched no row.\n  \"\"\"\n  id: Long\n}\n\n\"\"\"The `Duration` scalar type represents a duration of time.\"\"\"\nscalar Duration\n\n\"\"\"\nWhat a batch trigger did: triggerManifests or triggerGroups. The counts are of\nmanifests either way. A batch that could not be taken as given (no ids, or more than 1000)\nreturns Success = false with every count zero, having triggered nothing.\n\"\"\"\ntype BatchTriggerResponse {\n  \"\"\"\n  False only when the batch was refused as given; then nothing was triggered.\n  \"\"\"\n  success: Boolean!\n\n  \"\"\"\n  How many of the given ids named a manifest (or a group) that exists and was triggered.\n  \"\"\"\n  matched: Int!\n\n  \"\"\"Manifests a new work queue entry was queued for.\"\"\"\n  queued: Int!\n\n  \"\"\"\n  Manifests that already had a queued entry, so nothing more was queued: that entry became the\n  triggered run and was brought forward to now when it was due later. Also counts an entry the\n  dispatcher claimed before the trigger reached it, which is already running.\n  \"\"\"\n  alreadyQueued: Int!\n\n  \"\"\"\n  Manifests triggered to ask afresh whose queued retry the dispatcher claimed first, so that run\n  replays the decisions of the run it retries anyway. Zero unless the trigger asked afresh. Each\n  has a line in Notes naming the run it replays.\n  \"\"\"\n  tooLateToAskAfresh: Int!\n\n  \"\"\"\n  Given ids that named no manifest (or no group). Each has a line in Notes.\n  \"\"\"\n  skipped: Int!\n\n  \"\"\"One line saying what happened, for an operator.\"\"\"\n  message: String!\n\n  \"\"\"\n  One line per id that did not get what the trigger asked for: unknown, or still replaying.\n  Empty when every id was triggered as asked.\n  \"\"\"\n  notes: [BatchTriggerNote!]!\n}\n\n\"\"\"\nPatch input for operations.updateManifest. Every field is independent: a\nnull value leaves that field unchanged. Set ClearTimeout to remove\nthe per-execution timeout (since a null TimeoutSeconds means \"no\nchange\", not \"clear\").\n\"\"\"\ninput UpdateManifestInput {\n  isEnabled: Boolean\n  maxRetries: Int\n  priority: Int\n  timeoutSeconds: Int\n  clearTimeout: Boolean! = false\n  scheduleType: ScheduleType\n  cronExpression: String\n  intervalSeconds: Int\n}\n\n\"\"\"\nWhat operations.configureEffect did. Nothing is written unless every value is accepted.\n\"\"\"\ntype ConfigureEffectResponse {\n  \"\"\"Whether the settings were written.\"\"\"\n  success: Boolean!\n\n  \"\"\"How many settings were written; 0 on failure.\"\"\"\n  count: Int!\n\n  \"\"\"One line for an operator.\"\"\"\n  message: String!\n\n  \"\"\"\n  Why each refused setting was refused. Empty on success, and on a failure that is not one\n  setting's, such as an unknown effect.\n  \"\"\"\n  errors: [EffectSettingError!]!\n}\n\n\"\"\"One setting to write with operations.configureEffect.\"\"\"\ninput EffectSettingValueInput {\n  \"\"\"The setting's name, as Name gives it.\"\"\"\n  name: String!\n\n  \"\"\"\n  The value as text, read as the setting's type: numbers in invariant culture, a date or time\n  with no offset as UTC, a boolean as true or false, an enum by member name. Null\n  or blank is no value for a setting that accepts null and the empty string for a text setting\n  that does not.\n  \"\"\"\n  value: String\n}\n\n\"\"\"\nThe result of operations.cancelMachineInstance: what the cancel did, or why it did\nnothing, in the operations service's words, which the dashboard shows too.\n\"\"\"\ntype MachineInstanceCancelResponse {\n  \"\"\"True when the run was cancelled or its cancel requested.\"\"\"\n  success: Boolean!\n\n  \"\"\"What happened, or the typed reason nothing did.\"\"\"\n  outcome: MachineInstanceCancelOutcome!\n\n  \"\"\"The outcome in words.\"\"\"\n  message: String!\n\n  \"\"\"\n  The state the instance moved into, when this call moved it; null otherwise.\n  \"\"\"\n  state: String\n}\n\n\"\"\"Result of a single dead letter operation (requeue or acknowledge).\"\"\"\ntype DeadLetterOperationResult {\n  success: Boolean!\n  workQueueId: Long\n  message: String!\n}\n\n\"\"\"Result of a batch dead letter operation.\"\"\"\ntype BatchDeadLetterResult {\n  count: Int!\n  message: String!\n}\n\n\"\"\"\nRequest describing a train to queue for execution.\nShared input record used by both the GraphQL operations.workQueue.queueTrain\nmutation and the dashboard's QueueTrainDialog so both surfaces have identical\nvalidation and persistence semantics.\n\"\"\"\ninput QueueTrainInput {\n  \"\"\"\n  Fully qualified name of the train interface (matches what\n  operations.getTrains returns as ServiceTypeName).\n  \"\"\"\n  trainName: String!\n\n  \"\"\"\n  JSON payload that deserializes to the train's input type. null or blank is read as\n  an empty object, so a train whose input needs no values can be queued without one.\n  \"\"\"\n  inputJson: String\n\n  \"\"\"Dispatch priority 0-31. Higher values run first. Defaults to 0.\"\"\"\n  priority: Int! = 0\n\n  \"\"\"\n  Earliest UTC time the entry should be picked up. null means dispatch immediately.\n  \"\"\"\n  scheduledAt: DateTime\n}\n\n\"\"\"\nRequest describing a train to run now, on a worker, without going through the work queue.\nShared by the dashboard's Run dialog and any API surface that exposes a run, so both read\nthe input, authorize and submit the same way.\n\"\"\"\ninput RunTrainInput {\n  \"\"\"\n  Fully qualified name of the train interface, the same name\n  TrainName takes.\n  \"\"\"\n  trainName: String!\n\n  \"\"\"\n  JSON payload that deserializes to the train's input type. Property names match whatever their\n  case, and a property given twice is refused (docs/0023). null or blank is read as\n  an empty object, so a train whose input needs no values can be run without one.\n  \"\"\"\n  inputJson: String\n}\n\n\"\"\"\nPatch input for CancellationToken). Each field\nis independent: any property left null is left untouched. Pass only the values\nyou want to change.\n\"\"\"\ninput UpdateManifestGroupInput {\n  \"\"\"New per-group concurrency limit. Null = no change.\"\"\"\n  maxActiveJobs: Int\n\n  \"\"\"When true, sets MaxActiveJobs to null (removes the limit).\"\"\"\n  clearMaxActiveJobs: Boolean! = false\n\n  \"\"\"New priority. Null = no change.\"\"\"\n  priority: Int\n\n  \"\"\"Whether the group is active. Null = no change.\"\"\"\n  isEnabled: Boolean\n}\n\n\"\"\"\nPatch input for CancellationToken). Each\nfield is independent: null means \"leave unchanged\".\n\"\"\"\ninput UpdateSchedulerConfigInput {\n  manifestManagerEnabled: Boolean\n  jobDispatcherEnabled: Boolean\n  manifestManagerPollingInterval: Duration\n  jobDispatcherPollingInterval: Duration\n  maxActiveJobs: Int\n  clearMaxActiveJobs: Boolean! = false\n  defaultMaxRetries: Int\n  defaultRetryDelay: Duration\n  retryBackoffMultiplier: Float\n  maxRetryDelay: Duration\n  defaultJobTimeout: Duration\n  stalePendingTimeout: Duration\n  recoverStuckJobsOnStartup: Boolean\n  deadLetterRetentionPeriod: Duration\n  autoPurgeDeadLetters: Boolean\n  localWorkerCount: Int\n  clearLocalWorkerCount: Boolean! = false\n  metadataCleanupInterval: Duration\n  metadataCleanupRetention: Duration\n\n  \"\"\"\n  A new failure count window, or null to leave it unchanged. Must be between one\n  second and ten years.\n  \"\"\"\n  failureCountWindow: Duration\n}\n\n\"\"\"\nWhat config.setLogLevels did. A list naming an unknown category sets nothing.\n\"\"\"\ntype SetLogLevelsResponse {\n  \"\"\"Whether the levels were set.\"\"\"\n  success: Boolean!\n\n  \"\"\"How many categories were set; 0 on failure.\"\"\"\n  count: Int!\n\n  \"\"\"\n  Categories set whose loggers still filter at another level, which happens when the host sets\n  the filter itself after Trax. Empty on failure.\n  \"\"\"\n  notApplied: [String!]!\n\n  \"\"\"One line for an operator.\"\"\"\n  message: String!\n}\n\n\"\"\"A level to set for one category with config.setLogLevels.\"\"\"\ninput LogLevelSettingInput {\n  \"\"\"The category, as configured under Logging:LogLevel; case is ignored.\"\"\"\n  category: String!\n\n  \"\"\"The level to filter it at.\"\"\"\n  level: LogLevel!\n}\n\n\"\"\"Where one declared node stands in a run.\"\"\"\nenum RunNodeState {\n  \"\"\"No step was recorded for it, and nothing says it was passed over.\"\"\"\n  NOT_REACHED\n\n  \"\"\"Its junction has started and not yet returned.\"\"\"\n  IN_PROGRESS\n\n  \"\"\"Every step recorded for it completed.\"\"\"\n  COMPLETED\n\n  \"\"\"\n  A step recorded for it failed: the junction threw, or a decider's answer was refused.\n  \"\"\"\n  FAILED\n\n  \"\"\"A step recorded for it stopped because the run was asked to cancel.\"\"\"\n  CANCELLED\n\n  \"\"\"\n  It sits on a track the run did not take. A branch of a Parallel step is never passed\n  over, so a node there is skipped only when the step itself sits on such a track.\n  \"\"\"\n  SKIPPED\n\n  \"\"\"\n  A kind of step that records nothing when it runs (Extract, Seed, Resolve),\n  so the run cannot say whether it ran.\n  \"\"\"\n  NOT_RECORDED\n\n  \"\"\"\n  It comes after a route whose answer is withheld (a question about a [TraxSensitive]\n  type), so the steps the run recorded there name no node: which ran would give the answer away.\n  Those steps are in UnmatchedSteps.\n  \"\"\"\n  WITHHELD\n\n  \"\"\"\n  The run resumed from a checkpoint, and this node comes before the point it resumed at, so\n  the run skipped it and recorded no step for it: what the steps before the checkpoint\n  produced was restored from it instead.\n  \"\"\"\n  RESTORED\n\n  \"\"\"\n  Its junction started and never recorded an end, and the run has ended: the host stopped\n  mid-junction, or the step's end event was dropped. The step's row stays in progress, so the\n  node is read with the run's state rather than shown as still running.\n  \"\"\"\n  INTERRUPTED\n}\n\n\"\"\"\nWhat CancellationToken) did, or why it did nothing.\nThe first three are successes; the rest are refusals and change nothing.\n\"\"\"\nenum MachineInstanceCancelOutcome {\n  \"\"\"\n  The live run was still queued and is cancelled before it started, and this call moved the\n  instance through its OnCancelled edge.\n  \"\"\"\n  MOVED\n\n  \"\"\"\n  The live run was still queued and is cancelled before it started. The instance moves\n  through its OnCancelled edge when a host that registers the machine applies the\n  outcome (this host does not, or another delivery got there first).\n  \"\"\"\n  RUN_CANCELLED\n\n  \"\"\"\n  The live run was already dispatched, and its cancel is requested: it stops at its next\n  junction, ends Cancelled, and the instance then moves through its OnCancelled edge.\n  \"\"\"\n  CANCEL_REQUESTED\n\n  \"\"\"\n  The instance is owned by a user; operators may cancel only system-owned instances.\n  \"\"\"\n  USER_OWNED\n\n  \"\"\"No system-owned instance has this machine and id.\"\"\"\n  NOT_FOUND\n\n  \"\"\"\n  The instance's state waits on no train run, so there is nothing to cancel.\n  \"\"\"\n  NO_LIVE_RUN\n\n  \"\"\"\n  The live run has already ended; its outcome is being applied, and a cancel cannot change it.\n  \"\"\"\n  RUN_ENDED\n}\n\n\"\"\"A setting operations.configureEffect refused, and why.\"\"\"\ntype EffectSettingError {\n  \"\"\"The setting's name, as it was given.\"\"\"\n  field: String!\n\n  \"\"\"Why it was refused.\"\"\"\n  message: String!\n}\n\n\"\"\"\nOne id in a batch trigger, and what happened to it that the caller should know.\n\"\"\"\ntype BatchTriggerNote {\n  \"\"\"The id as given: a manifest id, or a group id.\"\"\"\n  id: Long!\n\n  \"\"\"What happened to it.\"\"\"\n  message: String!\n}\n\n\"\"\"\nOne per-train series for the 7-day throughput sparkline. The dashboard renders the\ntop 3 trains plus an \"Other\" series. The service emits the top-N (default 3) series\nplus an \"Other\" bucket in the same shape; consumers can render however they want.\n\"\"\"\ntype ThroughputSeries {\n  \"\"\"\n  Train interface FullName, or the literal string \"Other\" for the aggregated\n  remainder series.\n  \"\"\"\n  trainName: String!\n\n  \"\"\"28 buckets of 6 hours each, oldest first.\"\"\"\n  buckets: [ThroughputBucket!]!\n}\n\ntype TrainAverageDuration {\n  \"\"\"Train interface FullName.\"\"\"\n  trainName: String!\n\n  \"\"\"Mean execution time over completed root-level runs in the last 7 days.\"\"\"\n  averageMilliseconds: Float!\n}\n\ntype TrainFailureCount {\n  \"\"\"Train interface FullName as stored on Metadata.Name.\"\"\"\n  trainName: String!\n\n  \"\"\"Number of failures over the time window (last 7 days).\"\"\"\n  count: Int!\n}\n\n\"\"\"\nOne bucket of the executions-over-time chart, broken down by terminal state.\n\"\"\"\ntype ExecutionsBucket {\n  \"\"\"UTC start of the bucket.\"\"\"\n  timestamp: DateTime!\n\n  \"\"\"Count of completed executions in this bucket.\"\"\"\n  completed: Int!\n\n  \"\"\"Count of failed executions.\"\"\"\n  failed: Int!\n\n  \"\"\"Count of cancelled executions.\"\"\"\n  cancelled: Int!\n}\n\ntype DashboardKpis {\n  \"\"\"Total executions started today (UTC), all states.\"\"\"\n  executionsToday: Int!\n\n  \"\"\"\n  Completed / (Completed + Failed) as a percentage. Zero when no terminal executions.\n  \"\"\"\n  successRate: Float!\n\n  \"\"\"Executions in InProgress state right now.\"\"\"\n  currentlyRunning: Int!\n\n  \"\"\"Dead letters in AwaitingIntervention state.\"\"\"\n  unresolvedDeadLetters: Int!\n}\n\n\"\"\"\nOne log record written by a train while it ran, as the paged log read returns it.\n\"\"\"\ntype LogEntry {\n  \"\"\"The log record's id; pages are keyed on it.\"\"\"\n  id: Long!\n\n  \"\"\"\n  The id of the execution that wrote it, or 0 when the record names none. Trax's own log writer\n  does not record the run, so its records carry 0.\n  \"\"\"\n  metadataId: Long!\n\n  \"\"\"The EventId the message was logged with (0 when none was given).\"\"\"\n  eventId: Int!\n\n  \"\"\"The level it was logged at.\"\"\"\n  level: LogLevel!\n\n  \"\"\"\n  The logger category, usually the full name of the class that logged it.\n  \"\"\"\n  category: String!\n\n  \"\"\"The formatted message.\"\"\"\n  message: String!\n\n  \"\"\"The exception message, when one was logged with the record.\"\"\"\n  exception: String\n\n  \"\"\"The stack trace of that exception, when there is one.\"\"\"\n  stackTrace: String\n}\n\ntype DependencyGraphEdge {\n  \"\"\"Parent group ID (the group whose manifests are depended on).\"\"\"\n  fromId: Long!\n\n  \"\"\"Dependent group ID (the group whose manifests depend on the parent).\"\"\"\n  toId: Long!\n}\n\ntype DependencyGraphNode {\n  \"\"\"Database ID of the manifest group.\"\"\"\n  id: Long!\n\n  \"\"\"Group name as stored on the row.\"\"\"\n  name: String!\n\n  \"\"\"True for the focal group; the UI uses this to render it differently.\"\"\"\n  isHighlighted: Boolean!\n}\n\n\"\"\"Where a DeadLetterRequeueJob is.\"\"\"\nenum DeadLetterRequeueJobStatus {\n  \"\"\"The fold is still requeueing dead letters.\"\"\"\n  RUNNING\n\n  \"\"\"The fold finished; Count is what it requeued.\"\"\"\n  SUCCEEDED\n\n  \"\"\"\n  The fold stopped on a server failure. The detail is in the server's log only.\n  \"\"\"\n  FAILED\n\n  \"\"\"The node was shutting down, so the fold stopped between pages.\"\"\"\n  CANCELED\n}\n\n\"\"\"\nOne train run a state-machine instance invoked: the fields the run listings show, never its\ninput or output. executionDetail(id) reads the rest, with sensitive members masked.\n\"\"\"\ntype MachineInstanceInvokedRun {\n  \"\"\"The execution's id.\"\"\"\n  id: Long!\n\n  \"\"\"The execution's external id.\"\"\"\n  externalId: String!\n\n  \"\"\"The train that ran (the train interface's full name).\"\"\"\n  name: String!\n\n  \"\"\"Where the run is.\"\"\"\n  trainState: TrainState!\n\n  \"\"\"When it started (UTC).\"\"\"\n  startTime: DateTime!\n\n  \"\"\"When it ended (UTC), or null while it has not.\"\"\"\n  endTime: DateTime\n\n  \"\"\"How its failure was classified, or Unclassified.\"\"\"\n  failureClass: FailureClass!\n\n  \"\"\"Whether a cancel has been requested for it.\"\"\"\n  cancellationRequested: Boolean!\n\n  \"\"\"True for the run the instance's current state waits on.\"\"\"\n  isLive: Boolean!\n}\n\n\"\"\"\nOne state-machine instance in the operator's list: which machine, who owns it, what state it\nis in and when it got there.\n\"\"\"\ntype MachineInstance {\n  \"\"\"\n  The row's key. Pass it to machineInstance to read a user's draft, since several users\n  can each hold a draft under one id.\n  \"\"\"\n  rowId: Long!\n\n  \"\"\"The machine's id.\"\"\"\n  machine: String!\n\n  \"\"\"Whether a user or the system owns the instance.\"\"\"\n  ownerKind: SnapshotOwnerKind!\n\n  \"\"\"The instance or draft id.\"\"\"\n  id: UUID!\n\n  \"\"\"The state it is in.\"\"\"\n  state: String!\n\n  \"\"\"The machine definition version it was last written under.\"\"\"\n  version: Int!\n\n  \"\"\"When it was created, or null for one written before Trax recorded it.\"\"\"\n  createdAt: DateTime\n\n  \"\"\"When it was last written.\"\"\"\n  updatedAt: DateTime!\n\n  \"\"\"True while its state waits on the outcome of a train run it invoked.\"\"\"\n  hasLiveInvokedRun: Boolean!\n}\n\n\"\"\"Defines how the scheduler handles missed/overdue runs for a manifest.\"\"\"\nenum MisfirePolicy {\n  \"\"\"If overdue, fire once immediately. This is the default behavior.\"\"\"\n  FIRE_ONCE_NOW\n\n  \"\"\"\n  If overdue beyond the misfire threshold, skip and wait for the next natural\n  occurrence. For interval-based schedules, the scheduler advances to the most\n  recent interval boundary and checks whether we are within threshold of it.\n  \"\"\"\n  DO_NOTHING\n}\n\n\"\"\"\nThe `LocalTime` scalar type represents a time of day without date or time zone information.\n\"\"\"\nscalar LocalTime\n\n\"\"\"\nThe `LocalDate` scalar type represents a date without time or time zone information.\n\"\"\"\nscalar LocalDate\n\nenum DayOfWeek {\n  SUNDAY\n  MONDAY\n  TUESDAY\n  WEDNESDAY\n  THURSDAY\n  FRIDAY\n  SATURDAY\n}\n\n\"\"\"Defines the kind of exclusion window.\"\"\"\nenum ExclusionType {\n  \"\"\"Exclude specific days of the week (e.g., weekends).\"\"\"\n  DAYS_OF_WEEK\n\n  \"\"\"Exclude specific dates (e.g., holidays).\"\"\"\n  DATES\n\n  \"\"\"Exclude a contiguous date range (start–end inclusive).\"\"\"\n  DATE_RANGE\n\n  \"\"\"Exclude a daily time window (e.g., 2am–4am maintenance).\"\"\"\n  TIME_WINDOW\n}\n\n\"\"\"\nOne question a run asked a decider, as operations.decisions returns it: the answer the\nrun acted on (or refused) and the tracks routing steps took on it, with what must not be shown\nleft out.\n\"\"\"\ntype DecisionRecord {\n  \"\"\"The decision's id; decisions are recorded in id order.\"\"\"\n  id: Long!\n\n  \"\"\"The run that asked.\"\"\"\n  metadataId: Long!\n\n  \"\"\"The question's key; null on a withheld track.\"\"\"\n  questionKey: String\n\n  \"\"\"Which asking of the question this was in the run, from 0.\"\"\"\n  occurrence: Int!\n\n  \"\"\"choice, score or yes_no; null on a withheld track.\"\"\"\n  kind: String\n\n  \"\"\"The question as asked, as JSON; null on a withheld track.\"\"\"\n  question: String\n\n  \"\"\"\n  The answer the run acted on (for a refusal, the one it would not act on), as JSON; null when withheld.\n  \"\"\"\n  answer: String\n\n  \"\"\"\n  Why the run would not act on the answer; null for an answer it acted on, and when withheld.\n  \"\"\"\n  refused: String\n\n  \"\"\"True when the run refused the answer and its step failed on it.\"\"\"\n  isRefused: Boolean!\n\n  \"\"\"\n  Identifies the asking the answer was given to; null on a withheld track.\n  \"\"\"\n  fingerprint: String\n\n  \"\"\"\n  The model that answered, when the decider is a model; null on a withheld track.\n  \"\"\"\n  model: String\n\n  \"\"\"\n  The decider's type; null when the answer was replayed, or the track is withheld.\n  \"\"\"\n  decider: String\n\n  \"\"\"True when the answer came from an earlier run rather than a decider.\"\"\"\n  replayed: Boolean!\n\n  \"\"\"What each shadow decider answered, as JSON; null when withheld.\"\"\"\n  shadows: String\n\n  \"\"\"\n  The tracks routing steps took on the decision, as a JSON array; null when none did, or when withheld.\n  \"\"\"\n  routes: String\n\n  \"\"\"\n  The hash of the state the question was asked about; null when none was recorded, or the track is withheld.\n  \"\"\"\n  stateHash: String\n\n  \"\"\"When the question was answered (UTC).\"\"\"\n  decidedAt: DateTime!\n\n  \"\"\"True when the question is about a type marked [TraxSensitive].\"\"\"\n  answerWithheld: Boolean!\n\n  \"\"\"True when the run had already taken a track on a withheld answer.\"\"\"\n  trackWithheld: Boolean!\n\n  \"\"\"\n  Why an earlier run's answer was not replayed, so the decider was asked afresh: the\n  replay_refused member of Answer. Null when the answer carries none,\n  and when the answer is withheld.\n  \"\"\"\n  replayRefused: String\n}\n\n\"\"\"\nOne setting of a configurable effect: what it is, how it is edited, and its current value\nunless it is sensitive.\n\"\"\"\ntype EffectSettingInfo {\n  \"\"\"The property's name, which operations.configureEffect takes.\"\"\"\n  name: String!\n\n  \"\"\"The property's type name, without Nullable<>, such as Int32.\"\"\"\n  typeName: String!\n\n  \"\"\"\n  How the setting is edited: a switch, one of EnumValues, text, or not here at all.\n  \"\"\"\n  kind: EffectFieldKind!\n\n  \"\"\"\n  Whether the setting accepts no value; a null or blank value writes null.\n  \"\"\"\n  nullable: Boolean!\n\n  \"\"\"The member names, for an enum; null otherwise.\"\"\"\n  enumValues: [String!]\n\n  \"\"\"\n  True when the property is marked [TraxSensitive]: Value is always\n  null. It can still be written.\n  \"\"\"\n  sensitive: Boolean!\n\n  \"\"\"\n  Whether the setting holds a value (is not null). True for a sensitive setting that holds one.\n  \"\"\"\n  hasValue: Boolean!\n\n  \"\"\"\n  The current value as text, in the form configureEffect reads back; null when there is\n  none, when the setting is sensitive, and for SET_IN_CODE.\n  \"\"\"\n  value: String\n\n  \"\"\"What to type, such as yyyy-MM-dd HH:mm:ss (UTC).\"\"\"\n  hint: String!\n}\n\n\"\"\"Describes a single property on a train's input type.\"\"\"\ntype InputPropertySchema {\n  \"\"\"\n  The JSON name the input reader expects: the property name under the system JSON naming\n  policy, or its [JsonPropertyName] when it has one.\n  \"\"\"\n  name: String!\n\n  \"\"\"A readable name for the property's CLR type.\"\"\"\n  typeName: String!\n\n  \"\"\"Whether the property accepts null.\"\"\"\n  isNullable: Boolean!\n\n  \"\"\"\n  The values the property accepts when its type is an enum (or a nullable enum), spelled the way\n  the input reader expects them; null for any other type.\n  \"\"\"\n  enumValues: [String!]\n}\n\n\"\"\"\nBody of the operations.persistedOperations mutation namespace. Each mutation calls\nIPersistedOperationsService, which returns refusals as payload errors[]\nentries with stable code values; mutations never throw to the client.\n\"\"\"\ntype PersistedOperationMutations {\n  \"\"\"\n  Upload (insert or update) a persisted operation. Validates the document against the live\n  schema, requires exactly one operation, and rejects shape-changing edits unless\n  bypassShapeDiff is set.\n  \"\"\"\n  uploadPersistedOperation(input: UploadPersistedOperationInput!): UploadPersistedOperationPayload!\n\n  \"\"\"Soft-delete an operation. Requires a non-empty reason.\"\"\"\n  deactivatePersistedOperation(input: DeactivatePersistedOperationInput!): DeactivatePersistedOperationPayload!\n\n  \"\"\"Reactivate a previously deactivated operation.\"\"\"\n  restorePersistedOperation(input: RestorePersistedOperationInput!): RestorePersistedOperationPayload!\n}\n\n\"\"\"\nBody of the operations.persistedOperations query namespace. Each field calls\nIPersistedOperationsService.\n\"\"\"\ntype PersistedOperationQueries {\n  \"\"\"List persisted operations, most recently updated first, paginated.\"\"\"\n  persistedOperations(filter: PersistedOperationFilterInput, skip: Int! = 0, take: Int! = 50): PersistedOperationsPage!\n\n  \"\"\"Look up a single persisted operation. Returns null when missing.\"\"\"\n  persistedOperation(id: String!, tenantKey: String): PersistedOperationDto\n\n  \"\"\"Audit history for an operation, most-recent-first.\"\"\"\n  persistedOperationHistory(id: String!, tenantKey: String, skip: Int! = 0, take: Int! = 50): [PersistedOperationHistoryDto!]!\n}\n\n\"\"\"\nPayload for the onDataChanged subscription. Carries only which domain changed, not the\nchanged rows: a subscriber uses it as a nudge to refetch its (bounded, paged) view. Signals are\ncoalesced server-side, so one event stands in for a whole burst of writes to that domain.\n\"\"\"\ntype DataChangedEvent {\n  domain: ChangeDomain!\n  timestamp: DateTime!\n}\n\n\"\"\"\nIdentifies which slice of scheduler/admin data changed. Carried by\nITraxChangeSignal so a subscriber can refetch just the affected\nview instead of polling. The signal names the domain only, never row data.\n\"\"\"\nenum ChangeDomain {\n  \"\"\"The work queue (entries queued, dispatched, or cancelled).\"\"\"\n  WORK_QUEUE\n\n  \"\"\"\n  Dead letters (created when retries are exhausted, or requeued/acknowledged).\n  \"\"\"\n  DEAD_LETTER\n\n  \"\"\"Manifest scheduling/retry settings (edited, enabled, or disabled).\"\"\"\n  MANIFEST\n\n  \"\"\"Manifest group configuration.\"\"\"\n  MANIFEST_GROUP\n\n  \"\"\"Scheduler configuration.\"\"\"\n  SCHEDULER_CONFIG\n\n  \"\"\"Train runs (metadata rows), for example runs an operator cancelled.\"\"\"\n  EXECUTION\n}\n\n\"\"\"One row from the operation's audit log.\"\"\"\ntype PersistedOperationHistoryDto {\n  historyId: Long!\n  id: String!\n  tenantKey: String\n  document: String!\n  shapeFingerprint: String!\n  changeType: String!\n  changedAt: DateTime!\n  changedReason: String\n}\n\n\"\"\"GraphQL surface for a persisted operation row.\"\"\"\ntype PersistedOperationDto {\n  id: String!\n  tenantKey: String\n  operationName: String!\n  version: Int!\n  document: String!\n  shapeFingerprint: String!\n  isActive: Boolean!\n  deprecationReason: String\n  description: String\n  createdAt: DateTime!\n  updatedAt: DateTime!\n}\n\n\"\"\"Filter for the persistedOperations query.\"\"\"\ninput PersistedOperationFilterInput {\n  isActive: Boolean\n  tenantKey: String\n  idStartsWith: String\n}\n\n\"\"\"Paged result for the persistedOperations query.\"\"\"\ntype PersistedOperationsPage {\n  items: [PersistedOperationDto!]!\n  totalCount: Int!\n}\n\n\"\"\"Input for the restorePersistedOperation mutation.\"\"\"\ninput RestorePersistedOperationInput {\n  id: String!\n  tenantKey: String\n}\n\n\"\"\"Result of restorePersistedOperation.\"\"\"\ntype RestorePersistedOperationPayload {\n  operation: PersistedOperationDto\n  errors: [PersistedOperationError!]!\n\n  \"\"\"True when the change succeeded.\"\"\"\n  success: Boolean!\n}\n\n\"\"\"Input for the deactivatePersistedOperation mutation.\"\"\"\ninput DeactivatePersistedOperationInput {\n  id: String!\n  reason: String!\n  tenantKey: String\n}\n\n\"\"\"Result of deactivatePersistedOperation.\"\"\"\ntype DeactivatePersistedOperationPayload {\n  operation: PersistedOperationDto\n  errors: [PersistedOperationError!]!\n\n  \"\"\"True when the change succeeded.\"\"\"\n  success: Boolean!\n}\n\n\"\"\"Input for the uploadPersistedOperation mutation.\"\"\"\ninput UploadPersistedOperationInput {\n  id: String!\n  document: String!\n  description: String\n  bypassShapeDiff: Boolean! = false\n  version: Int! = 0\n  tenantKey: String\n}\n\n\"\"\"\nResult of uploadPersistedOperation. Exactly one of\nOperation and Errors is populated.\n\"\"\"\ntype UploadPersistedOperationPayload {\n  operation: PersistedOperationDto\n  errors: [PersistedOperationError!]!\n\n  \"\"\"True when the upload succeeded.\"\"\"\n  success: Boolean!\n}\n\n\"\"\"How a setting is edited.\"\"\"\nenum EffectFieldKind {\n  \"\"\"A switch: true or false.\"\"\"\n  BOOLEAN\n\n  \"\"\"One of EnumValues.\"\"\"\n  ENUM\n\n  \"\"\"\n  Text read as the property's type (a number, string, date, time, duration, GUID or character).\n  \"\"\"\n  TEXT\n\n  \"\"\"\n  A type with no text form (a delegate, a collection, an object): it is set in code and\n  cannot be written here.\n  \"\"\"\n  SET_IN_CODE\n}\n\ntype ThroughputBucket {\n  \"\"\"UTC start of the bucket.\"\"\"\n  timestamp: DateTime!\n\n  \"\"\"Number of completed executions in the bucket.\"\"\"\n  count: Int!\n}\n\n\"\"\"\nStructured error surfaced inside a mutation payload. Mutations never throw\nto the GraphQL caller; failures are returned in the errors field\nwith a stable code so clients can branch without string-matching.\n\"\"\"\ntype PersistedOperationError {\n  code: String!\n  message: String!\n  locations: [PersistedOperationErrorLocation!]\n  path: [String!]\n  oldFingerprint: String\n  newFingerprint: String\n}\n\n\"\"\"1-based location in the candidate document.\"\"\"\ntype PersistedOperationErrorLocation {\n  line: Int!\n  column: Int!\n}";
